/* uc_datacheck instance.json ...
 * Reports the data properties the formulation depends on. */
#include "instance.h"

#include <stdio.h>

int main(int argc, char **argv) {
    for (int a = 1; a < argc; a++) {
        char err[512];
        Instance *in = instance_load(argv[a], err, sizeof err);
        if (!in) { fprintf(stderr, "%s: %s\n", argv[a], err); return 1; }
        int n_must = 0, n_must_off = 0, n_must_down = 0, ut1 = 0, utmax = 0, dtmax = 0, ut_gt_T = 0, dt_gt_T = 0;
        int su_lt = 0, sd_lt = 0, su_gt = 0, sd_gt = 0, su_ne = 0, su_ne_ut1 = 0, su_ne_utgt1 = 0, fixedp = 0, pmin0 = 0;
        int p0_lo = 0, p0_hi = 0, p0_gt_sd = 0, off_p0 = 0, on_up0 = 0, on_down = 0, off_down0 = 0, off_up = 0;
        int need_up = 0, need_down = 0, hist_bad = 0, stuck = 0, ncat2 = 0, catmax = 0, tcmax = 0, segmax = 0, tcgt = 0;
        int ru_red = 0, rd_red = 0, ramp_su_gt_ru = 0, ramp_sd_gt_rd = 0;
        double cap = 0;
        for (int i = 0; i < in->ngen; i++) {
            const Gen *g = &in->gen[i];
            cap += g->pmax;
            if (g->must_run) { n_must++; if (!g->on0) n_must_off++; if (g->need_down) n_must_down++; }
            if (g->ut == 1) ut1++;
            if (g->ut > utmax) utmax = g->ut;
            if (g->dt > dtmax) dtmax = g->dt;
            if (g->ut > in->T) ut_gt_T++;
            if (g->dt > in->T) dt_gt_T++;
            if (g->su_raw < g->pmin - 1e-9) su_lt++;
            if (g->sd_raw < g->pmin - 1e-9) sd_lt++;
            if (g->su_raw > g->pmax + 1e-9) su_gt++;
            if (g->sd_raw > g->pmax + 1e-9) sd_gt++;
            if (g->su != g->sd) { su_ne++; if (g->ut == 1) su_ne_ut1++; else su_ne_utgt1++; }
            if (g->pmax - g->pmin <= 1e-9) fixedp++;
            if (g->pmin == 0) pmin0++;
            if (g->ru >= g->pmax - g->pmin) ru_red++;
            if (g->rd >= g->pmax - g->pmin) rd_red++;
            if (g->su - g->pmin > g->ru) ramp_su_gt_ru++;
            if (g->sd - g->pmin > g->rd) ramp_sd_gt_rd++;
            if (g->on0) {
                if (g->p0 < g->pmin - 1e-9) p0_lo++;
                if (g->p0 > g->pmax + 1e-9) p0_hi++;
                if (g->p0 > g->sd + 1e-9) p0_gt_sd++;
                if (g->up0 <= 0) on_up0++;
                if (g->down0 != 0) on_down++;
                /* History says the unit started up0 periods ago: is p(0) reachable? */
                if (g->up0 > 0 && g->p0 > g->su + (g->up0 - 1) * g->ru + 1e-7) hist_bad++;
                /* Must stay on at t=1 yet cannot ramp up to Pmin, or the reverse. */
                if (g->p0 + g->ru < g->pmin - 1e-9 && g->p0 > g->sd + 1e-9) stuck++;
            } else {
                if (g->p0 != 0) off_p0++;
                if (g->down0 <= 0) off_down0++;
                if (g->up0 != 0) off_up++;
            }
            if (g->need_up) need_up++;
            if (g->need_down) need_down++;
            if (g->ncat > 1) ncat2++;
            if (g->ncat > catmax) catmax = g->ncat;
            if (g->tc > tcmax) tcmax = g->tc;
            if (g->tc > in->T) tcgt++;
            if (g->nseg > segmax) segmax = g->nseg;
        }
        double dmax = 0, dmin = 1e300, rmax = 0, wmax = 0, wminmax = 0, peak_net = 0, peak_gross = 0;
        int ren_cross = 0, over_gross = 0, must_take_over = 0;
        double w_energy = 0, d_energy = 0;
        for (int t = 1; t <= in->T; t++) {
            double d = in->demand[t], r = in->reserve[t];
            if (d > dmax) dmax = d;
            if (d < dmin) dmin = d;
            if (r > rmax) rmax = r;
            if (in->ren_max[t] > wmax) wmax = in->ren_max[t];
            if (in->ren_min[t] > wminmax) wminmax = in->ren_min[t];
            if (in->ren_min[t] > in->ren_max[t]) ren_cross++;
            if (in->ren_min[t] > d) must_take_over++;
            if (d + r > peak_gross) peak_gross = d + r;
            if (d + r - in->ren_max[t] > peak_net) peak_net = d + r - in->ren_max[t];
            if (d + r > cap) over_gross++;
            w_energy += in->ren_max[t];
            d_energy += d;
        }
        printf("== %s\n", argv[a]);
        printf("T=%d gens=%d renewables=%d must_run=%d (off_t0=%d, with_D>0=%d)\n", in->T, in->ngen, in->nren, n_must, n_must_off, n_must_down);
