            if (g->su_raw > g->pmax + 1e-9) su_gt++;
            if (g->sd_raw > g->pmax + 1e-9) sd_gt++;
            if (g->su != g->sd) { su_ne++; if (g->ut == 1) su_ne_ut1++; else su_ne_utgt1++; }
            if (g->pmax - g->pmin <= 1e-9) fixedp++;
            if (g->pmin == 0) pmin0++;
            if (g->ru >= g->pmax - g->pmin) ru_red++;
            if (g->rd >= g->pmax - g->pmin) rd_red++;
