/* Equation numbers refer to Knueven, Ostrowski, Watson, "On Mixed Integer
 * Programming Formulations for the Unit Commitment Problem". NOTES.md explains
 * each place where the code differs from the printed text. */
#include "model.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define COEF_EPS 1e-11

static double pos(double x) { return x > 0 ? x : 0; }
static int imin(int a, int b) { return a < b ? a : b; }

typedef struct {
    /* columns */
    int ncol, capcol;
    double *obj, *lb, *ub;
    char *vtype;
    /* rows, in compressed form */
    int nrow, caprow, nnz, capnz;
    int *beg, *ind;
    double *val, *rhs;
    char *sense;
    int relax;
} Builder;

static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, n ? n : 1);
    if (!q) { fprintf(stderr, "out of memory\n"); exit(1); }
    return q;
}

static int add_col(Builder *b, double obj, double lb, double ub, char type) {
    if (b->ncol == b->capcol) {
        b->capcol = b->capcol ? 2 * b->capcol : 4096;
        b->obj = xrealloc(b->obj, (size_t)b->capcol * sizeof(double));
        b->lb = xrealloc(b->lb, (size_t)b->capcol * sizeof(double));
        b->ub = xrealloc(b->ub, (size_t)b->capcol * sizeof(double));
        b->vtype = xrealloc(b->vtype, (size_t)b->capcol);
    }
    b->obj[b->ncol] = obj;
    b->lb[b->ncol] = lb;
    b->ub[b->ncol] = ub;
    b->vtype[b->ncol] = type;
    return b->ncol++;
}

static int add_binary(Builder *b, double obj, double lb, double ub) {
    return add_col(b, obj, lb, ub, b->relax ? GRB_CONTINUOUS : GRB_BINARY);
}

static int add_cont(Builder *b, double obj) {
    return add_col(b, obj, 0.0, GRB_INFINITY, GRB_CONTINUOUS);
}

static void row_begin(Builder *b) {
    if (b->nrow == b->caprow) {
        b->caprow = b->caprow ? 2 * b->caprow : 4096;
        b->beg = xrealloc(b->beg, (size_t)b->caprow * sizeof(int));
        b->rhs = xrealloc(b->rhs, (size_t)b->caprow * sizeof(double));
        b->sense = xrealloc(b->sense, (size_t)b->caprow);
    }
    b->beg[b->nrow] = b->nnz;
}

static void row_add(Builder *b, int col, double coef) {
    if (fabs(coef) < COEF_EPS) return;
    if (b->nnz == b->capnz) {
        b->capnz = b->capnz ? 2 * b->capnz : 65536;
        b->ind = xrealloc(b->ind, (size_t)b->capnz * sizeof(int));
        b->val = xrealloc(b->val, (size_t)b->capnz * sizeof(double));
    }
    b->ind[b->nnz] = col;
    b->val[b->nnz] = coef;
    b->nnz++;
}

static void row_end(Builder *b, char sense, double rhs) {
    b->sense[b->nrow] = sense;
    b->rhs[b->nrow] = rhs;
    b->nrow++;
}

static int *new_index(int T) {
    int *a = xrealloc(NULL, (size_t)(T + 2) * sizeof(int));
    for (int t = 0; t < T + 2; t++) a[t] = -1;
    return a;
}

/* Everything needed to write coef*v(tau) or coef*w(tau) for any tau: inside the
 * horizon it is a variable, before it a known value, after it zero (Section 3). */
typedef struct {
    Builder *b;
    const Gen *g;
    const GenVars *x;
    int T, no_hist_v;
    double rhs;   /* accumulates the constants of the current <= row */
} RowCtx;

static void add_v(RowCtx *c, int tau, double coef) {
    if (tau > c->T) return;
    if (tau >= 1) row_add(c->b, c->x->v[tau], coef);
    else if (!c->no_hist_v && gen_hist_v(c->g, tau)) c->rhs -= coef;
}

static void add_w(RowCtx *c, int tau, double coef) {
    if (tau > c->T) return;
    if (tau >= 1) row_add(c->b, c->x->w[tau], coef);
    else if (gen_hist_w(c->g, tau)) c->rhs -= coef;
}

/* First period with a row (4) or (5), given the minimum time. */
static int updown_first(int min_time, int T, UpDownMode mode) {
    if (mode == UPDOWN_ALL_PERIODS) return 1;
    if (mode == UPDOWN_PRINTED) return min_time;
    return imin(min_time, T);
}

/* (2), (3) as bounds on u, (4), (5). */
static void add_updown(Builder *b, const Gen *g, const GenVars *x, int T, UpDownMode mode) {
    for (int t = 1; t <= T; t++) {
        row_begin(b);
        row_add(b, x->u[t], 1.0);
        if (t > 1) row_add(b, x->u[t - 1], -1.0);
        row_add(b, x->v[t], -1.0);
        row_add(b, x->w[t], 1.0);
        row_end(b, GRB_EQUAL, t == 1 ? (double)g->on0 : 0.0);
    }
    for (int t = updown_first(g->ut, T, mode); t <= T; t++) {
        double hist = 0;
        row_begin(b);
        for (int i = t - g->ut + 1; i <= t; i++) {
            if (i >= 1) row_add(b, x->v[i], 1.0);
            else if (gen_hist_v(g, i)) hist += 1.0;
        }
        row_add(b, x->u[t], -1.0);
        row_end(b, GRB_LESS_EQUAL, -hist);
    }
    for (int t = updown_first(g->dt, T, mode); t <= T; t++) {
        double hist = 0;
        row_begin(b);
        for (int i = t - g->dt + 1; i <= t; i++) {
            if (i >= 1) row_add(b, x->w[i], 1.0);
            else if (gen_hist_w(g, i)) hist += 1.0;
        }
        row_add(b, x->u[t], 1.0);
        row_end(b, GRB_LESS_EQUAL, 1.0 - hist);
    }
}

/* (17), (23), (38), (40), (41), stated in the p', pbar' variables by (12)-(15). */
static void add_generation_limits(Builder *b, const Gen *g, const GenVars *x, int T, const ModelOptions *o) {
    const double range = g->pmax - g->pmin;
    for (int t = 1; t <= T; t++) {
        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };

        /* (17) */
        row_begin(b);
        row_add(b, x->pp[t], 1.0);
        row_add(b, x->pa[t], -1.0);
        row_end(b, GRB_LESS_EQUAL, 0.0);

        if (g->ut == 1) {
            /* (23a) */
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pa[t], 1.0);
            row_add(b, x->u[t], -range);
            add_v(&c, t, g->pmax - g->su);
            add_w(&c, t + 1, pos(g->su - g->sd));
            row_end(b, GRB_LESS_EQUAL, c.rhs);
            /* (23b) */
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pa[t], 1.0);
            row_add(b, x->u[t], -range);
            add_w(&c, t + 1, g->pmax - g->sd);
            add_v(&c, t, pos(g->sd - g->su));
            row_end(b, GRB_LESS_EQUAL, c.rhs);
        }

        /* (38) */
        row_begin(b);
        c.rhs = 0;
        row_add(b, x->pa[t], 1.0);
        row_add(b, x->u[t], -range);
        add_w(&c, t + 1, g->pmax - g->sd);
        for (int i = 0; i <= imin(g->ut - 2, g->tru); i++)
            add_v(&c, t - i, g->pmax - g->su - i * g->ru);
        row_end(b, GRB_LESS_EQUAL, c.rhs);

        /* (40) */
        if (g->tru > g->ut - 2) {
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pa[t], 1.0);
            row_add(b, x->u[t], -range);
            for (int i = 0; i <= imin(g->ut - 1, g->tru); i++)
                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
            row_end(b, GRB_LESS_EQUAL, c.rhs);
        }

        /* (41): K^SD from (37); the printed K^SU refers to itself and is read with
         * [K^SD]^+ (NOTES.md). The left side is p', not pbar'. */
        int ksd = imin(imin(g->trd, g->ut - 1), T - t - 1);
        if (ksd > 0) {
            int ksu = imin(imin(g->tru, g->ut - 2 - ksd), t - 1);
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pp[t], 1.0);
            row_add(b, x->u[t], -range);
            for (int i = 0; i <= ksd; i++)
                add_w(&c, t + 1 + i, g->pmax - g->sd - i * g->rd);
            for (int i = 0; i <= ksu; i++)
                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
            if (ksu < g->tru) {
                double a = g->su + (ksu + 1) * g->ru;
                double coef = 0;
                if (o->tail == TAIL_PRINTED) coef = pos(a - (g->sd + g->trd * g->rd));
                else if (o->tail == TAIL_CORRECTED) coef = pos((g->sd + ksd * g->rd) - a);
                add_v(&c, t - (ksu + 1), coef);
            }
            row_end(b, GRB_LESS_EQUAL, c.rhs);
        }
    }
}

/* (35), (36). */
static void add_ramps(Builder *b, const Gen *g, const GenVars *x, int T) {
    const double pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
    for (int t = 1; t <= T; t++) {
        row_begin(b);
        row_add(b, x->pa[t], 1.0);
        if (t > 1) row_add(b, x->pp[t - 1], -1.0);
        row_add(b, x->v[t], -(g->su - g->pmin - g->ru));
        row_add(b, x->u[t], -g->ru);
        row_end(b, GRB_LESS_EQUAL, t == 1 ? pp0 : 0.0);

        double rhs = 0;
        row_begin(b);
        if (t > 1) {
            row_add(b, x->pp[t - 1], 1.0);
            row_add(b, x->u[t - 1], -g->rd);
        } else {
            rhs = g->rd * g->on0 - pp0;
        }
        row_add(b, x->pp[t], -1.0);
        row_add(b, x->w[t], -(g->sd - g->pmin - g->rd));
        row_end(b, GRB_LESS_EQUAL, rhs);
    }
}

/* C^v(l) or C^w(l) of (46): limit is SU or SD. */
static double seg_coef(const Gen *g, int l, double limit) {
    if (g->pw[l] <= limit) return 0.0;
    if (g->pw[l - 1] < limit) return g->pw[l] - limit;
    return g->pw[l] - g->pw[l - 1];
}

/* (43), (46) or (48); (44) is substituted into the objective. */
static void add_piecewise(Builder *b, const Gen *g, const GenVars *x, int **pl, int T, const ModelOptions *o) {
    for (int t = 1; t <= T; t++) {
        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };
        row_begin(b);
        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
        row_add(b, x->pp[t], -1.0);
        row_end(b, GRB_EQUAL, 0.0);

        for (int l = 1; l <= g->nseg; l++) {
            double d = g->pw[l] - g->pw[l - 1];
            double cv = seg_coef(g, l, g->su), cw = seg_coef(g, l, g->sd);
            if (g->ut > 1) {
                /* (46) */
                row_begin(b);
                row_add(b, pl[l][t], 1.0);
                row_add(b, x->u[t], -d);
                add_v(&c, t, cv);
                add_w(&c, t + 1, cw);
                row_end(b, GRB_LESS_EQUAL, 0.0);
            } else {
                /* (48). The printed operands of [.]^+ are reversed relative to (23);
                 * see NOTES.md. */
                double to_w = o->pw48_printed ? pos(cv - cw) : pos(cw - cv);
                double to_v = o->pw48_printed ? pos(cw - cv) : pos(cv - cw);
                row_begin(b);
                row_add(b, pl[l][t], 1.0);
                row_add(b, x->u[t], -d);
                add_v(&c, t, cv);
                add_w(&c, t + 1, to_w);
                row_end(b, GRB_LESS_EQUAL, 0.0);
                row_begin(b);
                row_add(b, pl[l][t], 1.0);
                row_add(b, x->u[t], -d);
                add_w(&c, t + 1, cw);
                add_v(&c, t, to_v);
                row_end(b, GRB_LESS_EQUAL, 0.0);
            }
        }
    }
}

/* A basic physical model built from (18), (19), (24), (25), (43), (42): the same
 * integer feasible set as T, with none of T's strengthening. Used only to test T. */
static void add_base_physical(Builder *b, const Gen *g, const GenVars *x, int **pl, int T) {
    const double range = g->pmax - g->pmin, pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
    for (int t = 1; t <= T; t++) {
        RowCtx c = { b, g, x, T, 1, 0.0 };
        row_begin(b);
        row_add(b, x->pp[t], 1.0);
        row_add(b, x->pa[t], -1.0);
        row_end(b, GRB_LESS_EQUAL, 0.0);
        row_begin(b);
        row_add(b, x->pa[t], 1.0);
        row_add(b, x->u[t], -range);
        add_w(&c, t + 1, g->pmax - g->sd);
        row_end(b, GRB_LESS_EQUAL, 0.0);

        /* (24) */
        double rhs = 0;
        row_begin(b);
        row_add(b, x->pa[t], 1.0);
        row_add(b, x->u[t], g->pmin);
        row_add(b, x->v[t], -g->su);
        if (t > 1) {
            row_add(b, x->pp[t - 1], -1.0);
            row_add(b, x->u[t - 1], -g->pmin - g->ru);
        } else {
            rhs = pp0 + g->on0 * (g->pmin + g->ru);
        }
        row_end(b, GRB_LESS_EQUAL, rhs);
        /* (25) */
        rhs = 0;
        row_begin(b);
        if (t > 1) {
            row_add(b, x->pp[t - 1], 1.0);
            row_add(b, x->u[t - 1], g->pmin);
        } else {
            rhs = -pp0 - g->on0 * g->pmin;
        }
        row_add(b, x->pp[t], -1.0);
        row_add(b, x->u[t], -g->pmin - g->rd);
        row_add(b, x->w[t], -g->sd);
        row_end(b, GRB_LESS_EQUAL, rhs);

        row_begin(b);
        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
        row_add(b, x->pp[t], -1.0);
        row_end(b, GRB_EQUAL, 0.0);
        for (int l = 1; l <= g->nseg; l++) {
            row_begin(b);
            row_add(b, pl[l][t], 1.0);
            row_add(b, x->u[t], -(g->pw[l] - g->pw[l - 1]));
            row_end(b, GRB_LESS_EQUAL, 0.0);
        }
    }
}

/* Variables x(t',t) of (59)-(61), for shut-down at t' and start-up at t with
 * DT <= t-t' <= TC-1, and the rows (59), (60). Their objective coefficients are
 * those of (61) after substitution into (69). Only one historical shut-down
 * exists: t' = 1-down0 for a unit that is off at period 0. */
static void add_startup(Builder *b, const Gen *g, const GenVars *x, int T) {
    const int S = g->ncat;
    if (S < 2 || g->tc <= g->dt) return;
    const double cold = g->scost[S - 1];
    int *xh = new_index(T);
    int *xm = xrealloc(NULL, (size_t)(T + 2) * (size_t)(T + 2) * sizeof(int));
    for (int k = 0; k < (T + 2) * (T + 2); k++) xm[k] = -1;

#define XM(tp, t) xm[(tp) * (T + 2) + (t)]
    for (int t = 1; t <= T; t++) {
        for (int tp = t - g->tc + 1; tp <= t - g->dt; tp++) {
            if (tp < 1 && !gen_hist_w(g, tp)) continue;
            int s = 0;
            while (s + 1 < S && g->lag[s + 1] <= t - tp) s++;
            int col = add_binary(b, -(cold - g->scost[s]), 0.0, 1.0);
            if (tp >= 1) XM(tp, t) = col;
            else xh[t] = col;
        }
    }
    /* (59) */
    for (int t = 1; t <= T; t++) {
        int any = 0;
        row_begin(b);
        for (int tp = 1; tp < t; tp++)
            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
        if (any) {
            row_add(b, x->v[t], -1.0);
            row_end(b, GRB_LESS_EQUAL, 0.0);
        } else {
            b->nnz = b->beg[b->nrow];
        }
    }
    /* (60) */
    for (int tp = 1; tp <= T; tp++) {
        int any = 0;
        row_begin(b);
        for (int t = tp + 1; t <= T; t++)
            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
        if (any) {
            row_add(b, x->w[tp], -1.0);
            row_end(b, GRB_LESS_EQUAL, 0.0);
        } else {
            b->nnz = b->beg[b->nrow];
        }
    }
    /* (60) at the historical shut-down, where w = 1 */
    int any = 0;
    row_begin(b);
    for (int t = 1; t <= T; t++)
        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
    if (any) row_end(b, GRB_LESS_EQUAL, 1.0);
    else b->nnz = b->beg[b->nrow];
#undef XM
    free(xm);
    free(xh);
}

void model_default_options(ModelOptions *o) {
    memset(o, 0, sizeof *o);
    o->tail = TAIL_CORRECTED;
    o->only_gen = -1;
}

int model_apply_variant(ModelOptions *o, const char *name) {
    if (!strcmp(name, "tail-none")) o->tail = TAIL_NONE;
    else if (!strcmp(name, "tail-printed")) o->tail = TAIL_PRINTED;
    else if (!strcmp(name, "tail-corrected")) o->tail = TAIL_CORRECTED;
    else if (!strcmp(name, "pw48-printed")) o->pw48_printed = 1;
    else if (!strcmp(name, "pw48-corrected")) o->pw48_printed = 0;
    else if (!strcmp(name, "reserve-printed")) o->reserve_printed = 1;
    else if (!strcmp(name, "reserve-renewables")) o->reserve_printed = 0;
    else if (!strcmp(name, "updown-literal")) o->updown_literal = 1;
    else if (!strcmp(name, "updown-truncated")) o->updown_literal = 0;
    else if (!strcmp(name, "no-hist-v")) o->no_hist_v = 1;
    else if (!strcmp(name, "base")) o->base_model = 1;
    else return 0;
    return 1;
}

int model_build(GRBenv *env, const Instance *in, const ModelOptions *o,
                GRBmodel **model_out, VarMap **map_out) {
    const int T = in->T;
    Builder bb, *b = &bb;
    memset(b, 0, sizeof *b);
    b->relax = o->relax;

    VarMap *m = xrealloc(NULL, sizeof *m);
    memset(m, 0, sizeof *m);
    m->T = T;
    m->ngen = in->ngen;
    m->gen = xrealloc(NULL, (size_t)in->ngen * sizeof *m->gen);
    memset(m->gen, 0, (size_t)in->ngen * sizeof *m->gen);

    for (int gi = 0; gi < in->ngen; gi++) {
        if (o->only_gen >= 0 && gi != o->only_gen) continue;
        const Gen *g = &in->gen[gi];
        GenVars *x = &m->gen[gi];
        x->u = new_index(T);
        x->v = new_index(T);
        x->w = new_index(T);
        x->pp = new_index(T);
        x->pa = new_index(T);
        int **pl = xrealloc(NULL, (size_t)(g->nseg + 1) * sizeof *pl);
        for (int l = 1; l <= g->nseg; l++) pl[l] = new_index(T);

        for (int t = 1; t <= T; t++) {
            double lb = 0.0, ub = 1.0;
            if (t <= imin(g->need_up, T)) lb = 1.0;          /* (3a) */
            if (t <= imin(g->need_down, T)) ub = 0.0;        /* (3b) */
            if (g->must_run) lb = 1.0;
            x->u[t] = add_binary(b, g->cr, lb, ub);
            x->v[t] = add_binary(b, g->scost[g->ncat - 1], 0.0, 1.0);
            x->w[t] = add_binary(b, 0.0, 0.0, 1.0);          /* C^w = 0 in (62) */
            x->pp[t] = add_cont(b, 0.0);
            x->pa[t] = add_cont(b, 0.0);
            for (int l = 1; l <= g->nseg; l++) pl[l][t] = add_cont(b, g->slope[l]);
        }

        add_updown(b, g, x, T, o->base_model ? 0 : o->updown_literal);
        if (o->base_model) {
            add_base_physical(b, g, x, pl, T);
        } else {
            add_generation_limits(b, g, x, T, o);
            add_ramps(b, g, x, T);
            add_piecewise(b, g, x, pl, T, o);
        }
        add_startup(b, g, x, T);

        for (int l = 1; l <= g->nseg; l++) free(pl[l]);
        free(pl);
    }

    if (o->only_gen < 0) {
        m->pw = new_index(T);
        m->splus = new_index(T);
        m->sminus = new_index(T);
        m->sr = new_index(T);
        for (int t = 1; t <= T; t++) {
            m->pw[t] = add_col(b, 0.0, in->ren_min[t], in->ren_max[t], GRB_CONTINUOUS);  /* (63) */
            m->splus[t] = add_cont(b, UC_C_LP);    /* (66) */
            m->sminus[t] = add_cont(b, UC_C_LP);
            m->sr[t] = add_cont(b, UC_C_RP);
        }
        for (int t = 1; t <= T; t++) {
            /* (65) with one bus: (64) is dropped and the flow sums are empty. */
            row_begin(b);
            for (int gi = 0; gi < in->ngen; gi++) {
                row_add(b, m->gen[gi].pp[t], 1.0);
                row_add(b, m->gen[gi].u[t], in->gen[gi].pmin);
            }
            row_add(b, m->pw[t], 1.0);
            row_add(b, m->splus[t], 1.0);
            row_add(b, m->sminus[t], -1.0);
            row_end(b, GRB_EQUAL, in->demand[t]);

            /* (67), by default with the renewable term (NOTES.md). */
            row_begin(b);
            for (int gi = 0; gi < in->ngen; gi++) {
                row_add(b, m->gen[gi].pa[t], 1.0);
                row_add(b, m->gen[gi].u[t], in->gen[gi].pmin);
            }
            if (!o->reserve_printed) row_add(b, m->pw[t], 1.0);
            row_add(b, m->sr[t], 1.0);
            row_end(b, GRB_GREATER_EQUAL, in->demand[t] + in->reserve[t]);
        }
    }

    GRBmodel *model = NULL;
    int err = GRBnewmodel(env, &model, "uc_T", b->ncol, b->obj, b->lb, b->ub, b->vtype, NULL);
    if (!err) err = GRBsetintattr(model, GRB_INT_ATTR_MODELSENSE, GRB_MINIMIZE);
    if (!err) err = GRBaddconstrs(model, b->nrow, b->nnz, b->beg, b->ind, b->val, b->sense, b->rhs, NULL);
    if (!err) err = GRBupdatemodel(model);
    m->numvars = b->ncol;

    free(b->obj); free(b->lb); free(b->ub); free(b->vtype);
    free(b->beg); free(b->ind); free(b->val); free(b->rhs); free(b->sense);

    if (err) {
        if (model) GRBfreemodel(model);
        varmap_free(m);
        return err;
    }
    *model_out = model;
    *map_out = m;
    return 0;
}

void varmap_free(VarMap *m) {
    if (!m) return;
    for (int g = 0; g < m->ngen; g++) {
        free(m->gen[g].u); free(m->gen[g].v); free(m->gen[g].w);
        free(m->gen[g].pp); free(m->gen[g].pa);
    }
    free(m->gen);
    free(m->pw); free(m->splus); free(m->sminus); free(m->sr);
    free(m);
}

/* Equation numbers refer to Knueven, Ostrowski, Watson, "On Mixed Integer
 * Programming Formulations for the Unit Commitment Problem". NOTES.md explains
 * each place where the code differs from the printed text. */
#include "model.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define COEF_EPS 1e-11

static double pos(double x) { return x > 0 ? x : 0; }
static int imin(int a, int b) { return a < b ? a : b; }

typedef struct {
    /* columns */
    int ncol, capcol;
    double *obj, *lb, *ub;
    char *vtype;
    /* rows, in compressed form */
    int nrow, caprow, nnz, capnz;
    int *beg, *ind;
    double *val, *rhs;
    char *sense;
    int relax;
} Builder;

static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, n ? n : 1);
    if (!q) { fprintf(stderr, "out of memory\n"); exit(1); }
    return q;
}

static int add_col(Builder *b, double obj, double lb, double ub, char type) {
    if (b->ncol == b->capcol) {
        b->capcol = b->capcol ? 2 * b->capcol : 4096;
        b->obj = xrealloc(b->obj, (size_t)b->capcol * sizeof(double));
        b->lb = xrealloc(b->lb, (size_t)b->capcol * sizeof(double));
        b->ub = xrealloc(b->ub, (size_t)b->capcol * sizeof(double));
        b->vtype = xrealloc(b->vtype, (size_t)b->capcol);
    }
    b->obj[b->ncol] = obj;
    b->lb[b->ncol] = lb;
    b->ub[b->ncol] = ub;
    b->vtype[b->ncol] = type;
    return b->ncol++;
}

static int add_binary(Builder *b, double obj, double lb, double ub) {
    return add_col(b, obj, lb, ub, b->relax ? GRB_CONTINUOUS : GRB_BINARY);
}

static int add_cont(Builder *b, double obj) {
    return add_col(b, obj, 0.0, GRB_INFINITY, GRB_CONTINUOUS);
}

static void row_begin(Builder *b) {
    if (b->nrow == b->caprow) {
        b->caprow = b->caprow ? 2 * b->caprow : 4096;
        b->beg = xrealloc(b->beg, (size_t)b->caprow * sizeof(int));
        b->rhs = xrealloc(b->rhs, (size_t)b->caprow * sizeof(double));
        b->sense = xrealloc(b->sense, (size_t)b->caprow);
    }
    b->beg[b->nrow] = b->nnz;
}

static void row_add(Builder *b, int col, double coef) {
    if (fabs(coef) < COEF_EPS) return;
    if (b->nnz == b->capnz) {
        b->capnz = b->capnz ? 2 * b->capnz : 65536;
        b->ind = xrealloc(b->ind, (size_t)b->capnz * sizeof(int));
        b->val = xrealloc(b->val, (size_t)b->capnz * sizeof(double));
    }
    b->ind[b->nnz] = col;
    b->val[b->nnz] = coef;
    b->nnz++;
}

static void row_end(Builder *b, char sense, double rhs) {
    b->sense[b->nrow] = sense;
    b->rhs[b->nrow] = rhs;
    b->nrow++;
}

static int *new_index(int T) {
    int *a = xrealloc(NULL, (size_t)(T + 2) * sizeof(int));
    for (int t = 0; t < T + 2; t++) a[t] = -1;
    return a;
}

/* Everything needed to write coef*v(tau) or coef*w(tau) for any tau: inside the
 * horizon it is a variable, before it a known value, after it zero (Section 3). */
typedef struct {
    Builder *b;
    const Gen *g;
    const GenVars *x;
    int T, no_hist_v;
    double rhs;   /* accumulates the constants of the current <= row */
} RowCtx;

static void add_v(RowCtx *c, int tau, double coef) {
    if (tau > c->T) return;
    if (tau >= 1) row_add(c->b, c->x->v[tau], coef);
    else if (!c->no_hist_v && gen_hist_v(c->g, tau)) c->rhs -= coef;
}

static void add_w(RowCtx *c, int tau, double coef) {
    if (tau > c->T) return;
    if (tau >= 1) row_add(c->b, c->x->w[tau], coef);
    else if (gen_hist_w(c->g, tau)) c->rhs -= coef;
}

/* First period with a row (4) or (5), given the minimum time. */
static int updown_first(int min_time, int T, UpDownMode mode) {
    if (mode == UPDOWN_ALL_PERIODS) return 1;
    if (mode == UPDOWN_PRINTED) return min_time;
    return imin(min_time, T);
}

/* (2), (3) as bounds on u, (4), (5). */
static void add_updown(Builder *b, const Gen *g, const GenVars *x, int T, UpDownMode mode) {
    for (int t = 1; t <= T; t++) {
        row_begin(b);
        row_add(b, x->u[t], 1.0);
        if (t > 1) row_add(b, x->u[t - 1], -1.0);
        row_add(b, x->v[t], -1.0);
        row_add(b, x->w[t], 1.0);
        row_end(b, GRB_EQUAL, t == 1 ? (double)g->on0 : 0.0);
    }
    for (int t = updown_first(g->ut, T, mode); t <= T; t++) {
        double hist = 0;
        row_begin(b);
        for (int i = t - g->ut + 1; i <= t; i++) {
            if (i >= 1) row_add(b, x->v[i], 1.0);
            else if (gen_hist_v(g, i)) hist += 1.0;
        }
        row_add(b, x->u[t], -1.0);
        row_end(b, GRB_LESS_EQUAL, -hist);
    }
    for (int t = updown_first(g->dt, T, mode); t <= T; t++) {
        double hist = 0;
        row_begin(b);
        for (int i = t - g->dt + 1; i <= t; i++) {
            if (i >= 1) row_add(b, x->w[i], 1.0);
            else if (gen_hist_w(g, i)) hist += 1.0;
        }
        row_add(b, x->u[t], 1.0);
        row_end(b, GRB_LESS_EQUAL, 1.0 - hist);
    }
}

/* (17), (23), (38), (40), (41), stated in the p', pbar' variables by (12)-(15). */
static void add_generation_limits(Builder *b, const Gen *g, const GenVars *x, int T, const ModelOptions *o) {
    const double range = g->pmax - g->pmin;
    for (int t = 1; t <= T; t++) {
        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };

        /* (17) */
        row_begin(b);
        row_add(b, x->pp[t], 1.0);
        row_add(b, x->pa[t], -1.0);
        row_end(b, GRB_LESS_EQUAL, 0.0);

        if (g->ut == 1) {
            /* (23a) */
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pa[t], 1.0);
            row_add(b, x->u[t], -range);
            add_v(&c, t, g->pmax - g->su);
            add_w(&c, t + 1, pos(g->su - g->sd));
            row_end(b, GRB_LESS_EQUAL, c.rhs);
            /* (23b) */
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pa[t], 1.0);
            row_add(b, x->u[t], -range);
            add_w(&c, t + 1, g->pmax - g->sd);
            add_v(&c, t, pos(g->sd - g->su));
            row_end(b, GRB_LESS_EQUAL, c.rhs);
        }

        /* (38) */
        row_begin(b);
        c.rhs = 0;
        row_add(b, x->pa[t], 1.0);
        row_add(b, x->u[t], -range);
        add_w(&c, t + 1, g->pmax - g->sd);
        for (int i = 0; i <= imin(g->ut - 2, g->tru); i++)
            add_v(&c, t - i, g->pmax - g->su - i * g->ru);
        row_end(b, GRB_LESS_EQUAL, c.rhs);

        /* (40) */
        if (g->tru > g->ut - 2) {
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pa[t], 1.0);
            row_add(b, x->u[t], -range);
            for (int i = 0; i <= imin(g->ut - 1, g->tru); i++)
                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
            row_end(b, GRB_LESS_EQUAL, c.rhs);
        }

        /* (41): K^SD from (37); the printed K^SU refers to itself and is read with
         * [K^SD]^+ (NOTES.md). The left side is p', not pbar'. */
        int ksd = imin(imin(g->trd, g->ut - 1), T - t - 1);
        if (ksd > 0) {
            int ksu = imin(imin(g->tru, g->ut - 2 - ksd), t - 1);
            row_begin(b);
            c.rhs = 0;
            row_add(b, x->pp[t], 1.0);
            row_add(b, x->u[t], -range);
            for (int i = 0; i <= ksd; i++)
                add_w(&c, t + 1 + i, g->pmax - g->sd - i * g->rd);
            for (int i = 0; i <= ksu; i++)
                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
            if (ksu < g->tru) {
                double a = g->su + (ksu + 1) * g->ru;
                double coef = 0;
                if (o->tail == TAIL_PRINTED) coef = pos(a - (g->sd + g->trd * g->rd));
                else if (o->tail == TAIL_CORRECTED) coef = pos((g->sd + ksd * g->rd) - a);
                add_v(&c, t - (ksu + 1), coef);
            }
            row_end(b, GRB_LESS_EQUAL, c.rhs);
        }
    }
}

/* (35), (36). */
static void add_ramps(Builder *b, const Gen *g, const GenVars *x, int T) {
    const double pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
    for (int t = 1; t <= T; t++) {
        row_begin(b);
        row_add(b, x->pa[t], 1.0);
        if (t > 1) row_add(b, x->pp[t - 1], -1.0);
        row_add(b, x->v[t], -(g->su - g->pmin - g->ru));
        row_add(b, x->u[t], -g->ru);
        row_end(b, GRB_LESS_EQUAL, t == 1 ? pp0 : 0.0);

        double rhs = 0;
        row_begin(b);
        if (t > 1) {
            row_add(b, x->pp[t - 1], 1.0);
            row_add(b, x->u[t - 1], -g->rd);
        } else {
            rhs = g->rd * g->on0 - pp0;
        }
        row_add(b, x->pp[t], -1.0);
        row_add(b, x->w[t], -(g->sd - g->pmin - g->rd));
        row_end(b, GRB_LESS_EQUAL, rhs);
    }
}

/* C^v(l) or C^w(l) of (46): limit is SU or SD. */
static double seg_coef(const Gen *g, int l, double limit) {
    if (g->pw[l] <= limit) return 0.0;
    if (g->pw[l - 1] < limit) return g->pw[l] - limit;
    return g->pw[l] - g->pw[l - 1];
}

/* (43), (46) or (48); (44) is substituted into the objective. */
static void add_piecewise(Builder *b, const Gen *g, const GenVars *x, int **pl, int T, const ModelOptions *o) {
    for (int t = 1; t <= T; t++) {
        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };
        row_begin(b);
        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
        row_add(b, x->pp[t], -1.0);
        row_end(b, GRB_EQUAL, 0.0);

        for (int l = 1; l <= g->nseg; l++) {
            double d = g->pw[l] - g->pw[l - 1];
            double cv = seg_coef(g, l, g->su), cw = seg_coef(g, l, g->sd);
            if (g->ut > 1) {
                /* (46) */
                row_begin(b);
                row_add(b, pl[l][t], 1.0);
                row_add(b, x->u[t], -d);
                add_v(&c, t, cv);
                add_w(&c, t + 1, cw);
                row_end(b, GRB_LESS_EQUAL, 0.0);
            } else {
                /* (48). The printed operands of [.]^+ are reversed relative to (23);
                 * see NOTES.md. */
                double to_w = o->pw48_printed ? pos(cv - cw) : pos(cw - cv);
                double to_v = o->pw48_printed ? pos(cw - cv) : pos(cv - cw);
                row_begin(b);
                row_add(b, pl[l][t], 1.0);
                row_add(b, x->u[t], -d);
                add_v(&c, t, cv);
                add_w(&c, t + 1, to_w);
                row_end(b, GRB_LESS_EQUAL, 0.0);
                row_begin(b);
                row_add(b, pl[l][t], 1.0);
                row_add(b, x->u[t], -d);
                add_w(&c, t + 1, cw);
                add_v(&c, t, to_v);
                row_end(b, GRB_LESS_EQUAL, 0.0);
            }
        }
    }
}

/* A basic physical model built from (18), (19), (24), (25), (43), (42): the same
 * integer feasible set as T, with none of T's strengthening. Used only to test T. */
static void add_base_physical(Builder *b, const Gen *g, const GenVars *x, int **pl, int T) {
    const double range = g->pmax - g->pmin, pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
    for (int t = 1; t <= T; t++) {
        RowCtx c = { b, g, x, T, 1, 0.0 };
        row_begin(b);
        row_add(b, x->pp[t], 1.0);
        row_add(b, x->pa[t], -1.0);
        row_end(b, GRB_LESS_EQUAL, 0.0);
        row_begin(b);
        row_add(b, x->pa[t], 1.0);
        row_add(b, x->u[t], -range);
        add_w(&c, t + 1, g->pmax - g->sd);
        row_end(b, GRB_LESS_EQUAL, 0.0);

        /* (24) */
        double rhs = 0;
        row_begin(b);
        row_add(b, x->pa[t], 1.0);
        row_add(b, x->u[t], g->pmin);
        row_add(b, x->v[t], -g->su);
        if (t > 1) {
            row_add(b, x->pp[t - 1], -1.0);
            row_add(b, x->u[t - 1], -g->pmin - g->ru);
        } else {
            rhs = pp0 + g->on0 * (g->pmin + g->ru);
        }
        row_end(b, GRB_LESS_EQUAL, rhs);
        /* (25) */
        rhs = 0;
        row_begin(b);
        if (t > 1) {
            row_add(b, x->pp[t - 1], 1.0);
            row_add(b, x->u[t - 1], g->pmin);
        } else {
            rhs = -pp0 - g->on0 * g->pmin;
        }
        row_add(b, x->pp[t], -1.0);
        row_add(b, x->u[t], -g->pmin - g->rd);
        row_add(b, x->w[t], -g->sd);
        row_end(b, GRB_LESS_EQUAL, rhs);

        row_begin(b);
        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
        row_add(b, x->pp[t], -1.0);
        row_end(b, GRB_EQUAL, 0.0);
        for (int l = 1; l <= g->nseg; l++) {
            row_begin(b);
            row_add(b, pl[l][t], 1.0);
            row_add(b, x->u[t], -(g->pw[l] - g->pw[l - 1]));
            row_end(b, GRB_LESS_EQUAL, 0.0);
        }
    }
}

/* Variables x(t',t) of (59)-(61), for shut-down at t' and start-up at t with
 * DT <= t-t' <= TC-1, and the rows (59), (60). Their objective coefficients are
 * those of (61) after substitution into (69). Only one historical shut-down
 * exists: t' = 1-down0 for a unit that is off at period 0. */
static void add_startup(Builder *b, const Gen *g, const GenVars *x, int T) {
    const int S = g->ncat;
    if (S < 2 || g->tc <= g->dt) return;
    const double cold = g->scost[S - 1];
    int *xh = new_index(T);
    int *xm = xrealloc(NULL, (size_t)(T + 2) * (size_t)(T + 2) * sizeof(int));
    for (int k = 0; k < (T + 2) * (T + 2); k++) xm[k] = -1;

#define XM(tp, t) xm[(tp) * (T + 2) + (t)]
    for (int t = 1; t <= T; t++) {
        for (int tp = t - g->tc + 1; tp <= t - g->dt; tp++) {
            if (tp < 1 && !gen_hist_w(g, tp)) continue;
            int s = 0;
            while (s + 1 < S && g->lag[s + 1] <= t - tp) s++;
            int col = add_binary(b, -(cold - g->scost[s]), 0.0, 1.0);
            if (tp >= 1) XM(tp, t) = col;
            else xh[t] = col;
        }
    }
    /* (59) */
    for (int t = 1; t <= T; t++) {
        int any = 0;
        row_begin(b);
        for (int tp = 1; tp < t; tp++)
            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
        if (any) {
            row_add(b, x->v[t], -1.0);
            row_end(b, GRB_LESS_EQUAL, 0.0);
        } else {
            b->nnz = b->beg[b->nrow];
        }
    }
    /* (60) */
    for (int tp = 1; tp <= T; tp++) {
        int any = 0;
        row_begin(b);
        for (int t = tp + 1; t <= T; t++)
            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
        if (any) {
            row_add(b, x->w[tp], -1.0);
            row_end(b, GRB_LESS_EQUAL, 0.0);
        } else {
            b->nnz = b->beg[b->nrow];
        }
    }
    /* (60) at the historical shut-down, where w = 1 */
    int any = 0;
    row_begin(b);
    for (int t = 1; t <= T; t++)
        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
    if (any) row_end(b, GRB_LESS_EQUAL, 1.0);
    else b->nnz = b->beg[b->nrow];
#undef XM
    free(xm);
    free(xh);
}

void model_default_options(ModelOptions *o) {
    memset(o, 0, sizeof *o);
    o->tail = TAIL_CORRECTED;
    o->only_gen = -1;
}

int model_apply_variant(ModelOptions *o, const char *name) {
    if (!strcmp(name, "tail-none")) o->tail = TAIL_NONE;
    else if (!strcmp(name, "tail-printed")) o->tail = TAIL_PRINTED;
    else if (!strcmp(name, "tail-corrected")) o->tail = TAIL_CORRECTED;
    else if (!strcmp(name, "pw48-printed")) o->pw48_printed = 1;
    else if (!strcmp(name, "pw48-corrected")) o->pw48_printed = 0;
    else if (!strcmp(name, "reserve-printed")) o->reserve_printed = 1;
    else if (!strcmp(name, "reserve-renewables")) o->reserve_printed = 0;
    else if (!strcmp(name, "updown-clamped")) o->updown = UPDOWN_CLAMPED;
    else if (!strcmp(name, "updown-printed")) o->updown = UPDOWN_PRINTED;
    else if (!strcmp(name, "updown-all-periods")) o->updown = UPDOWN_ALL_PERIODS;
    else if (!strcmp(name, "no-hist-v")) o->no_hist_v = 1;
    else if (!strcmp(name, "base")) o->base_model = 1;
    else return 0;
    return 1;
}

int model_build(GRBenv *env, const Instance *in, const ModelOptions *o,
                GRBmodel **model_out, VarMap **map_out) {
    const int T = in->T;
    Builder bb, *b = &bb;
    memset(b, 0, sizeof *b);
    b->relax = o->relax;

    VarMap *m = xrealloc(NULL, sizeof *m);
    memset(m, 0, sizeof *m);
    m->T = T;
    m->ngen = in->ngen;
    m->gen = xrealloc(NULL, (size_t)in->ngen * sizeof *m->gen);
    memset(m->gen, 0, (size_t)in->ngen * sizeof *m->gen);

    for (int gi = 0; gi < in->ngen; gi++) {
        if (o->only_gen >= 0 && gi != o->only_gen) continue;
        const Gen *g = &in->gen[gi];
        GenVars *x = &m->gen[gi];
        x->u = new_index(T);
        x->v = new_index(T);
        x->w = new_index(T);
        x->pp = new_index(T);
        x->pa = new_index(T);
        int **pl = xrealloc(NULL, (size_t)(g->nseg + 1) * sizeof *pl);
        for (int l = 1; l <= g->nseg; l++) pl[l] = new_index(T);

        for (int t = 1; t <= T; t++) {
            double lb = 0.0, ub = 1.0;
            if (t <= imin(g->need_up, T)) lb = 1.0;          /* (3a) */
            if (t <= imin(g->need_down, T)) ub = 0.0;        /* (3b) */
            if (g->must_run) lb = 1.0;
            x->u[t] = add_binary(b, g->cr, lb, ub);
            x->v[t] = add_binary(b, g->scost[g->ncat - 1], 0.0, 1.0);
            x->w[t] = add_binary(b, 0.0, 0.0, 1.0);          /* C^w = 0 in (62) */
            x->pp[t] = add_cont(b, 0.0);
            x->pa[t] = add_cont(b, 0.0);
            for (int l = 1; l <= g->nseg; l++) pl[l][t] = add_cont(b, g->slope[l]);
        }

        add_updown(b, g, x, T, o->base_model ? 0 : o->updown_literal);
        if (o->base_model) {
            add_base_physical(b, g, x, pl, T);
        } else {
            add_generation_limits(b, g, x, T, o);
            add_ramps(b, g, x, T);
            add_piecewise(b, g, x, pl, T, o);
        }
        add_startup(b, g, x, T);

        for (int l = 1; l <= g->nseg; l++) free(pl[l]);
        free(pl);
    }

    if (o->only_gen < 0) {
        m->pw = new_index(T);
        m->splus = new_index(T);
        m->sminus = new_index(T);
        m->sr = new_index(T);
        for (int t = 1; t <= T; t++) {
            m->pw[t] = add_col(b, 0.0, in->ren_min[t], in->ren_max[t], GRB_CONTINUOUS);  /* (63) */
            m->splus[t] = add_cont(b, UC_C_LP);    /* (66) */
            m->sminus[t] = add_cont(b, UC_C_LP);
            m->sr[t] = add_cont(b, UC_C_RP);
        }
        for (int t = 1; t <= T; t++) {
            /* (65) with one bus: (64) is dropped and the flow sums are empty. */
            row_begin(b);
            for (int gi = 0; gi < in->ngen; gi++) {
                row_add(b, m->gen[gi].pp[t], 1.0);
                row_add(b, m->gen[gi].u[t], in->gen[gi].pmin);
            }
            row_add(b, m->pw[t], 1.0);
            row_add(b, m->splus[t], 1.0);
            row_add(b, m->sminus[t], -1.0);
            row_end(b, GRB_EQUAL, in->demand[t]);

            /* (67), by default with the renewable term (NOTES.md). */
            row_begin(b);
            for (int gi = 0; gi < in->ngen; gi++) {
                row_add(b, m->gen[gi].pa[t], 1.0);
                row_add(b, m->gen[gi].u[t], in->gen[gi].pmin);
            }
            if (!o->reserve_printed) row_add(b, m->pw[t], 1.0);
            row_add(b, m->sr[t], 1.0);
            row_end(b, GRB_GREATER_EQUAL, in->demand[t] + in->reserve[t]);
        }
    }

    GRBmodel *model = NULL;
    int err = GRBnewmodel(env, &model, "uc_T", b->ncol, b->obj, b->lb, b->ub, b->vtype, NULL);
    if (!err) err = GRBsetintattr(model, GRB_INT_ATTR_MODELSENSE, GRB_MINIMIZE);
    if (!err) err = GRBaddconstrs(model, b->nrow, b->nnz, b->beg, b->ind, b->val, b->sense, b->rhs, NULL);
    if (!err) err = GRBupdatemodel(model);
    m->numvars = b->ncol;

    free(b->obj); free(b->lb); free(b->ub); free(b->vtype);
    free(b->beg); free(b->ind); free(b->val); free(b->rhs); free(b->sense);

    if (err) {
        if (model) GRBfreemodel(model);
        varmap_free(m);
        return err;
    }
    *model_out = model;
    *map_out = m;
    return 0;
}

void varmap_free(VarMap *m) {
    if (!m) return;
    for (int g = 0; g < m->ngen; g++) {
        free(m->gen[g].u); free(m->gen[g].v); free(m->gen[g].w);
        free(m->gen[g].pp); free(m->gen[g].pa);
    }
    free(m->gen);
    free(m->pw); free(m->splus); free(m->sminus); free(m->sr);
    free(m);
}

#include "instance.h"
#include "json.h"

#include <math.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MW_TOL 1e-9

static void *xcalloc(size_t n, size_t sz) {
    void *p = calloc(n ? n : 1, sz);
    if (!p) { fprintf(stderr, "out of memory\n"); exit(1); }
    return p;
}

static char *xstrdup(const char *s) {
    char *d = xcalloc(strlen(s) + 1, 1);
    strcpy(d, s);
    return d;
}

static int seterr(char *err, unsigned long len, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(err, len, fmt, ap);
    va_end(ap);
    return 0;
}

static int get_num(const JsonValue *o, const char *key, const char *ctx, double *out,
                   char *err, unsigned long errlen) {
    const JsonValue *v = json_get(o, key);
    if (!v) return seterr(err, errlen, "%s: missing field '%s'", ctx, key);
    if (v->type != JSON_NUMBER && v->type != JSON_BOOL)
        return seterr(err, errlen, "%s: field '%s' is not a number", ctx, key);
    *out = v->number;
    return 1;
}

static int get_int(const JsonValue *o, const char *key, const char *ctx, int *out,
                   int *n_rounded, char *err, unsigned long errlen) {
    double d;
    if (!get_num(o, key, ctx, &d, err, errlen)) return 0;
    *out = (int)lround(d);
    if (fabs(d - *out) > 1e-9) (*n_rounded)++;
    return 1;
}

static int get_series(const JsonValue *o, const char *key, const char *ctx, int T, double *out,
                      char *err, unsigned long errlen) {
    const JsonValue *v = json_get(o, key);
    if (!v) return seterr(err, errlen, "%s: missing field '%s'", ctx, key);
    if (v->type != JSON_ARRAY || (int)v->count != T)
        return seterr(err, errlen, "%s: field '%s' is not an array of length %d", ctx, key, T);
    for (int t = 0; t < T; t++) {
        if (v->items[t].type != JSON_NUMBER)
            return seterr(err, errlen, "%s: '%s'[%d] is not a number", ctx, key, t);
        out[t] = v->items[t].number;
    }
    return 1;
}

/* Floor of a ratio that is exact up to rounding error in the data. */
static int floor_ratio(double num, double den) {
    return (int)floor(num / den + 1e-9);
}

/* Evaluate the file's cost curve at mw, extending the end segments if needed. */
static double curve_value(const double *mw, const double *cost, int n, double x) {
    if (n == 1) return cost[0];
    int k = 0;
    while (k < n - 2 && x > mw[k + 1]) k++;
    double d = mw[k + 1] - mw[k];
    if (d <= 0) return cost[k];
    return cost[k] + (cost[k + 1] - cost[k]) * (x - mw[k]) / d;
}

static int load_startup(Instance *inst, Gen *g, const JsonValue *jg, char *err, unsigned long errlen) {
    const JsonValue *js = json_get(jg, "startup");
    if (!js || js->type != JSON_ARRAY || js->count == 0)
        return seterr(err, errlen, "%s: 'startup' must be a non-empty array", g->name);
    int n = (int)js->count;
    int *lag = xcalloc((size_t)n, sizeof *lag);
    double *cost = xcalloc((size_t)n, sizeof *cost);
    for (int k = 0; k < n; k++) {
        int r = 0;
        if (!get_int(&js->items[k], "lag", g->name, &lag[k], &r, err, errlen) ||
            !get_num(&js->items[k], "cost", g->name, &cost[k], err, errlen)) {
            free(lag); free(cost);
            return 0;
        }
        inst->n_int_rounded += r;
        if (k > 0 && lag[k] <= lag[k - 1]) inst->n_lag_not_increasing++;
        if (k > 0 && cost[k] < cost[k - 1]) inst->n_scost_decreasing++;
    }
    if (lag[0] < g->dt) inst->n_lag_first_lt_dt++;
    if (lag[0] > g->dt) inst->n_lag_first_gt_dt++;

    /* Paper: T^1 = DT and T^S = TC. An off period shorter than DT cannot occur, so
     * a category whose whole range lies below DT is unreachable and is dropped.
     * The last category with lag <= DT becomes the hottest; if every lag exceeds
     * DT, the first category is extended down to DT. */
    int first = 0;
    for (int k = 0; k < n; k++) if (lag[k] <= g->dt) first = k;
    if (first > 0) inst->n_cat_merged++;
    g->ncat = n - first;
    g->lag = xcalloc((size_t)g->ncat, sizeof *g->lag);
    g->scost = xcalloc((size_t)g->ncat, sizeof *g->scost);
    for (int k = 0; k < g->ncat; k++) {
        g->lag[k] = lag[first + k];
        g->scost[k] = cost[first + k];
    }
    g->lag[0] = g->dt;
    g->tc = g->lag[g->ncat - 1];
    free(lag);
    free(cost);
    return 1;
}

static int load_curve(Instance *inst, Gen *g, const JsonValue *jg, char *err, unsigned long errlen) {
    const JsonValue *jp = json_get(jg, "piecewise_production");
    if (!jp || jp->type != JSON_ARRAY || jp->count == 0)
        return seterr(err, errlen, "%s: 'piecewise_production' must be a non-empty array", g->name);
    int n = (int)jp->count;
    double *mw = xcalloc((size_t)n, sizeof *mw);
    double *cost = xcalloc((size_t)n, sizeof *cost);
    for (int k = 0; k < n; k++) {
        if (!get_num(&jp->items[k], "mw", g->name, &mw[k], err, errlen) ||
            !get_num(&jp->items[k], "cost", g->name, &cost[k], err, errlen)) {
            free(mw); free(cost);
            return 0;
        }
    }
    int dup = 0, nonconvex = 0;
    double prev = -INFINITY;
    for (int k = 1; k < n; k++) {
        double d = mw[k] - mw[k - 1];
        if (d <= MW_TOL) { dup = 1; continue; }
        double s = (cost[k] - cost[k - 1]) / d;
        if (s < prev - 1e-7) nonconvex = 1;
        prev = s;
    }
    if (dup) inst->n_pw_dup++;
    if (nonconvex) inst->n_pw_nonconvex++;
    if (fabs(mw[0] - g->pmin) > MW_TOL) inst->n_pw_first_ne_pmin++;
    if (fabs(mw[n - 1] - g->pmax) > MW_TOL) inst->n_pw_last_ne_pmax++;

    /* Paper: Pbar^0 = P_ and Pbar^l > P_ for every l. Restrict the curve to
     * [Pmin, Pmax], interpolating at the ends and dropping repeated points. */
    g->cr = curve_value(mw, cost, n, g->pmin);
    g->pw = xcalloc((size_t)n + 2, sizeof *g->pw);
    g->slope = xcalloc((size_t)n + 2, sizeof *g->slope);
    g->pw[0] = g->pmin;
    int L = 0;
    double last_cost = g->cr;
    for (int k = 0; k < n; k++) {
        if (mw[k] <= g->pw[L] + MW_TOL) continue;
        if (mw[k] >= g->pmax - MW_TOL) break;
        L++;
        g->pw[L] = mw[k];
        g->slope[L] = (cost[k] - last_cost) / (g->pw[L] - g->pw[L - 1]);
        last_cost = cost[k];
    }
    if (g->pmax > g->pw[L] + MW_TOL) {
        double c = curve_value(mw, cost, n, g->pmax);
        L++;
        g->pw[L] = g->pmax;
        g->slope[L] = (c - last_cost) / (g->pw[L] - g->pw[L - 1]);
    }
    g->nseg = L;
    free(mw);
    free(cost);
    return 1;
}

static int load_gen(Instance *inst, Gen *g, const char *key, const JsonValue *jg,
                    char *err, unsigned long errlen) {
    g->name = xstrdup(key);
    const JsonValue *jn = json_get(jg, "name");
    if (jn && jn->type == JSON_STRING && strcmp(jn->string, key) != 0) inst->n_name_mismatch++;
    if (jg->type != JSON_OBJECT) return seterr(err, errlen, "%s: not an object", key);

    int *r = &inst->n_int_rounded;
    if (!get_int(jg, "must_run", key, &g->must_run, r, err, errlen) ||
        !get_num(jg, "power_output_minimum", key, &g->pmin, err, errlen) ||
        !get_num(jg, "power_output_maximum", key, &g->pmax, err, errlen) ||
        !get_num(jg, "ramp_up_limit", key, &g->ru, err, errlen) ||
        !get_num(jg, "ramp_down_limit", key, &g->rd, err, errlen) ||
        !get_num(jg, "ramp_startup_limit", key, &g->su_raw, err, errlen) ||
        !get_num(jg, "ramp_shutdown_limit", key, &g->sd_raw, err, errlen) ||
        !get_int(jg, "time_up_minimum", key, &g->ut, r, err, errlen) ||
        !get_int(jg, "time_down_minimum", key, &g->dt, r, err, errlen) ||
        !get_int(jg, "unit_on_t0", key, &g->on0, r, err, errlen) ||
        !get_num(jg, "power_output_t0", key, &g->p0, err, errlen) ||
        !get_int(jg, "time_up_t0", key, &g->up0, r, err, errlen) ||
        !get_int(jg, "time_down_t0", key, &g->down0, r, err, errlen))
        return 0;

    if (g->pmax < g->pmin) return seterr(err, errlen, "%s: maximum power is below minimum", key);
    if (g->ru <= 0 || g->rd <= 0) return seterr(err, errlen, "%s: ramp rates must be positive", key);

    /* The formulation has no meaning for UT or DT below one period. */
    if (g->ut < 1) g->ut = 1;
    if (g->dt < 1) g->dt = 1;

    /* A limit above Pbar never binds; clipping keeps Pbar-SU and Pbar-SD nonnegative. */
    g->su = g->su_raw < g->pmax ? g->su_raw : g->pmax;
    g->sd = g->sd_raw < g->pmax ? g->sd_raw : g->pmax;

    g->tru = floor_ratio(g->pmax - g->su, g->ru);
    g->trd = floor_ratio(g->pmax - g->sd, g->rd);

    g->need_up = g->on0 && g->ut > g->up0 ? g->ut - g->up0 : 0;
    g->need_down = !g->on0 && g->dt > g->down0 ? g->dt - g->down0 : 0;

    return load_startup(inst, g, jg, err, errlen) && load_curve(inst, g, jg, err, errlen);
}

Instance *instance_load(const char *path, char *err, unsigned long errlen) {
    JsonValue *root = json_parse_file(path, err, errlen);
    if (!root) return NULL;
    Instance *inst = xcalloc(1, sizeof *inst);
    int ok = 0;

    do {
        if (root->type != JSON_OBJECT) { seterr(err, errlen, "top level is not an object"); break; }
        int r = 0;
        if (!get_int(root, "time_periods", "top level", &inst->T, &r, err, errlen)) break;
        int T = inst->T;
        if (T < 1) { seterr(err, errlen, "time_periods must be positive"); break; }
        inst->demand = xcalloc((size_t)T + 2, sizeof(double));
        inst->reserve = xcalloc((size_t)T + 2, sizeof(double));
        inst->ren_min = xcalloc((size_t)T + 2, sizeof(double));
        inst->ren_max = xcalloc((size_t)T + 2, sizeof(double));
        if (!get_series(root, "demand", "top level", T, inst->demand + 1, err, errlen)) break;
        if (!get_series(root, "reserves", "top level", T, inst->reserve + 1, err, errlen)) break;

        const JsonValue *jr = json_get(root, "renewable_generators");
        if (!jr || jr->type != JSON_OBJECT) { seterr(err, errlen, "missing 'renewable_generators'"); break; }
        inst->nren = (int)jr->count;
        double *lo = xcalloc((size_t)T, sizeof *lo), *hi = xcalloc((size_t)T, sizeof *hi);
        int good = 1;
        for (size_t k = 0; k < jr->count && good; k++) {
            good = get_series(&jr->items[k], "power_output_minimum", jr->keys[k], T, lo, err, errlen) &&
                   get_series(&jr->items[k], "power_output_maximum", jr->keys[k], T, hi, err, errlen);
            for (int t = 0; good && t < T; t++) {
                inst->ren_min[t + 1] += lo[t];
                inst->ren_max[t + 1] += hi[t];
            }
        }
        free(lo);
        free(hi);
        if (!good) break;

        const JsonValue *jt = json_get(root, "thermal_generators");
        if (!jt || jt->type != JSON_OBJECT) { seterr(err, errlen, "missing 'thermal_generators'"); break; }
        inst->ngen = (int)jt->count;
        inst->gen = xcalloc((size_t)inst->ngen, sizeof *inst->gen);
        for (int g = 0; g < inst->ngen && good; g++)
            good = load_gen(inst, &inst->gen[g], jt->keys[g], &jt->items[g], err, errlen);
        if (!good) break;
        ok = 1;
    } while (0);

    json_free(root);
    if (!ok) { instance_free(inst); return NULL; }
    return inst;
}

void instance_free(Instance *inst) {
    if (!inst) return;
    if (inst->gen) {
        for (int g = 0; g < inst->ngen; g++) {
            free(inst->gen[g].name);
            free(inst->gen[g].lag);
            free(inst->gen[g].scost);
            free(inst->gen[g].pw);
            free(inst->gen[g].slope);
        }
    }
    free(inst->gen);
    free(inst->demand);
    free(inst->reserve);
    free(inst->ren_min);
    free(inst->ren_max);
    free(inst);
}

static int warn(FILE *out, const char *what, int count, const char *example) {
    if (count == 0) return 0;
    fprintf(out, "data warning: %s: %d", what, count);
    if (example) fprintf(out, " (e.g. %s)", example);
    fputc('\n', out);
    return 1;
}

int instance_warnings(const Instance *in, FILE *out) {
    enum {
        UT_GT_T, DT_GT_T, SU_LT_PMIN, SD_LT_PMIN, SU_GT_PMAX, SD_GT_PMAX, MUST_OFF, MUST_DOWN,
        P0_LOW, P0_HIGH, ON_NO_UP, ON_DOWN, OFF_P0, OFF_NO_DOWN, OFF_UP,
        HIST_TRAJ, CANNOT_STAY, NKIND
    };
    static const char *label[NKIND] = {
        "generators with UT > T, so (4) as printed has no rows",
        "generators with DT > T, so (5) as printed has no rows",
        "generators with SU below minimum power (cannot start)",
        "generators with SD below minimum power (cannot stop)",
        "generators with SU above maximum power (clipped)",
        "generators with SD above maximum power (clipped)",
        "must-run generators off in period 0",
        "must-run generators required to stay off at the start",
        "generators on in period 0 below minimum power",
        "generators on in period 0 above maximum power",
        "generators on in period 0 with time_up_t0 <= 0",
        "generators on in period 0 with time_down_t0 != 0",
        "generators off in period 0 with nonzero output",
        "generators off in period 0 with time_down_t0 <= 0",
        "generators off in period 0 with time_up_t0 != 0",
        "generators whose p(0) exceeds SU + (time_up_t0-1) RU, contradicting historical v",
        "generators on in period 0 that can neither shut down nor reach minimum power",
    };
    int count[NKIND] = { 0 };
    const char *first[NKIND] = { 0 };
#define FLAG(kind) do { if (!count[kind]++) first[kind] = g->name; } while (0)
    for (int i = 0; i < in->ngen; i++) {
        const Gen *g = &in->gen[i];
        if (g->ut > in->T) FLAG(UT_GT_T);
        if (g->dt > in->T) FLAG(DT_GT_T);
        if (g->su_raw < g->pmin - MW_TOL) FLAG(SU_LT_PMIN);
        if (g->sd_raw < g->pmin - MW_TOL) FLAG(SD_LT_PMIN);
        if (g->su_raw > g->pmax + MW_TOL) FLAG(SU_GT_PMAX);
        if (g->sd_raw > g->pmax + MW_TOL) FLAG(SD_GT_PMAX);
        if (g->must_run && !g->on0) FLAG(MUST_OFF);
        if (g->must_run && g->need_down) FLAG(MUST_DOWN);
        if (g->on0) {
            if (g->p0 < g->pmin - MW_TOL) FLAG(P0_LOW);
            if (g->p0 > g->pmax + MW_TOL) FLAG(P0_HIGH);
            if (g->up0 <= 0) FLAG(ON_NO_UP);
            if (g->down0 != 0) FLAG(ON_DOWN);
            if (g->up0 > 0 && g->p0 > g->su + (g->up0 - 1) * g->ru + 1e-7) FLAG(HIST_TRAJ);
            if (g->p0 > g->sd + MW_TOL && g->p0 + g->ru < g->pmin - MW_TOL) FLAG(CANNOT_STAY);
        } else {
            if (g->p0 != 0) FLAG(OFF_P0);
            if (g->down0 <= 0) FLAG(OFF_NO_DOWN);
            if (g->up0 != 0) FLAG(OFF_UP);
        }
    }
#undef FLAG
    int lines = 0;
    for (int k = 0; k < NKIND; k++) lines += warn(out, label[k], count[k], first[k]);
    lines += warn(out, "generators whose name field differs from their key", in->n_name_mismatch, NULL);
    lines += warn(out, "generators whose first start-up lag is below DT", in->n_lag_first_lt_dt, NULL);
    lines += warn(out, "generators whose first start-up lag is above DT", in->n_lag_first_gt_dt, NULL);
    lines += warn(out, "generators with start-up categories unreachable because of DT", in->n_cat_merged, NULL);
    lines += warn(out, "start-up lags not strictly increasing", in->n_lag_not_increasing, NULL);
    lines += warn(out, "start-up costs that decrease with lag", in->n_scost_decreasing, NULL);
    lines += warn(out, "curves whose first point is not at minimum power", in->n_pw_first_ne_pmin, NULL);
    lines += warn(out, "curves whose last point is not at maximum power", in->n_pw_last_ne_pmax, NULL);
    lines += warn(out, "curves with repeated mw points", in->n_pw_dup, NULL);
    lines += warn(out, "curves that are not convex", in->n_pw_nonconvex, NULL);
    lines += warn(out, "integer fields with non-integer values (rounded)", in->n_int_rounded, NULL);
    return lines;
}

int gen_hist_v(const Gen *g, int tau) {
    return g->on0 && g->up0 > 0 && tau == 1 - g->up0;
}

int gen_hist_w(const Gen *g, int tau) {
    return !g->on0 && g->down0 > 0 && tau == 1 - g->down0;
}

