11	#define COEF_EPS 1e-11
12	
13	static double pos(double x) { return x > 0 ? x : 0; }
14	static int imin(int a, int b) { return a < b ? a : b; }
15	
16	typedef struct {
17	    /* columns */
18	    int ncol, capcol;
19	    double *obj, *lb, *ub;
20	    char *vtype;
21	    /* rows, in compressed form */
22	    int nrow, caprow, nnz, capnz;
23	    int *beg, *ind;
24	    double *val, *rhs;
25	    char *sense;
26	    int relax;
27	} Builder;
