29	static void *xrealloc(void *p, size_t n) {
30	    void *q = realloc(p, n ? n : 1);
31	    if (!q) { fprintf(stderr, "out of memory\n"); exit(1); }
32	    return q;
33	}
34	
35	static int add_col(Builder *b, double obj, double lb, double ub, char type) {
36	    if (b->ncol == b->capcol) {
37	        b->capcol = b->capcol ? 2 * b->capcol : 4096;
38	        b->obj = xrealloc(b->obj, (size_t)b->capcol * sizeof(double));
39	        b->lb = xrealloc(b->lb, (size_t)b->capcol * sizeof(double));
40	        b->ub = xrealloc(b->ub, (size_t)b->capcol * sizeof(double));
41	        b->vtype = xrealloc(b->vtype, (size_t)b->capcol);
42	    }
43	    b->obj[b->ncol] = obj;
44	    b->lb[b->ncol] = lb;
45	    b->ub[b->ncol] = ub;
46	    b->vtype[b->ncol] = type;
47	    return b->ncol++;
48	}
49	
50	static int add_binary(Builder *b, double obj, double lb, double ub) {
51	    return add_col(b, obj, lb, ub, b->relax ? GRB_CONTINUOUS : GRB_BINARY);
52	}
53	
54	static int add_cont(Builder *b, double obj) {
55	    return add_col(b, obj, 0.0, GRB_INFINITY, GRB_CONTINUOUS);
56	}
57	
58	static void row_begin(Builder *b) {
59	    if (b->nrow == b->caprow) {
60	        b->caprow = b->caprow ? 2 * b->caprow : 4096;
61	        b->beg = xrealloc(b->beg, (size_t)b->caprow * sizeof(int));
62	        b->rhs = xrealloc(b->rhs, (size_t)b->caprow * sizeof(double));
63	        b->sense = xrealloc(b->sense, (size_t)b->caprow);
64	    }
65	    b->beg[b->nrow] = b->nnz;
66	}
67	
68	static void row_add(Builder *b, int col, double coef) {
69	    if (fabs(coef) < COEF_EPS) return;
70	    if (b->nnz == b->capnz) {
71	        b->capnz = b->capnz ? 2 * b->capnz : 65536;
72	        b->ind = xrealloc(b->ind, (size_t)b->capnz * sizeof(int));
73	        b->val = xrealloc(b->val, (size_t)b->capnz * sizeof(double));
74	    }
75	    b->ind[b->nnz] = col;
76	    b->val[b->nnz] = coef;
77	    b->nnz++;
78	}
79	
80	static void row_end(Builder *b, char sense, double rhs) {
81	    b->sense[b->nrow] = sense;
82	    b->rhs[b->nrow] = rhs;
83	    b->nrow++;
84	}
85	
86	static int *new_index(int T) {
87	    int *a = xrealloc(NULL, (size_t)(T + 2) * sizeof(int));
88	    for (int t = 0; t < T + 2; t++) a[t] = -1;
89	    return a;
90	}
91	
92	/* Everything needed to write coef*v(tau) or coef*w(tau) for any tau: inside the
93	 * horizon it is a variable, before it a known value, after it zero (Section 3). */
94	typedef struct {
95	    Builder *b;
96	    const Gen *g;
97	    const GenVars *x;
98	    int T, no_hist_v;
99	    double rhs;   /* accumulates the constants of the current <= row */
100	} RowCtx;
101	
102	static void add_v(RowCtx *c, int tau, double coef) {
103	    if (tau > c->T) return;
104	    if (tau >= 1) row_add(c->b, c->x->v[tau], coef);
105	    else if (!c->no_hist_v && gen_hist_v(c->g, tau)) c->rhs -= coef;
106	}
107	
108	static void add_w(RowCtx *c, int tau, double coef) {
109	    if (tau > c->T) return;
110	    if (tau >= 1) row_add(c->b, c->x->w[tau], coef);
111	    else if (gen_hist_w(c->g, tau)) c->rhs -= coef;
112	}
113	
114	/* First period with a row (4) or (5), given the minimum time. */
115	static int updown_first(int min_time, int T, UpDownMode mode) {
116	    if (mode == UPDOWN_ALL_PERIODS) return 1;
117	    if (mode == UPDOWN_PRINTED) return min_time;
118	    return imin(min_time, T);
119	}
120	
121	/* (2), (3) as bounds on u, (4), (5). */
122	static void add_updown(Builder *b, const Gen *g, const GenVars *x, int T, UpDownMode mode) {
123	    for (int t = 1; t <= T; t++) {
124	        row_begin(b);
125	        row_add(b, x->u[t], 1.0);
126	        if (t > 1) row_add(b, x->u[t - 1], -1.0);
127	        row_add(b, x->v[t], -1.0);
128	        row_add(b, x->w[t], 1.0);
129	        row_end(b, GRB_EQUAL, t == 1 ? (double)g->on0 : 0.0);
130	    }
131	    for (int t = updown_first(g->ut, T, mode); t <= T; t++) {
132	        double hist = 0;
133	        row_begin(b);
134	        for (int i = t - g->ut + 1; i <= t; i++) {
135	            if (i >= 1) row_add(b, x->v[i], 1.0);
136	            else if (gen_hist_v(g, i)) hist += 1.0;
137	        }
138	        row_add(b, x->u[t], -1.0);
139	        row_end(b, GRB_LESS_EQUAL, -hist);
140	    }
141	    for (int t = updown_first(g->dt, T, mode); t <= T; t++) {
142	        double hist = 0;
143	        row_begin(b);
144	        for (int i = t - g->dt + 1; i <= t; i++) {
145	            if (i >= 1) row_add(b, x->w[i], 1.0);
146	            else if (gen_hist_w(g, i)) hist += 1.0;
147	        }
148	        row_add(b, x->u[t], 1.0);
149	        row_end(b, GRB_LESS_EQUAL, 1.0 - hist);
150	    }
151	}
152	
153	/* (17), (23), (38), (40), (41), stated in the p', pbar' variables by (12)-(15). */
154	static void add_generation_limits(Builder *b, const Gen *g, const GenVars *x, int T, const ModelOptions *o) {
155	    const double range = g->pmax - g->pmin;
156	    for (int t = 1; t <= T; t++) {
157	        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };
158	
159	        /* (17) */
160	        row_begin(b);
161	        row_add(b, x->pp[t], 1.0);
162	        row_add(b, x->pa[t], -1.0);
163	        row_end(b, GRB_LESS_EQUAL, 0.0);
164	
165	        if (g->ut == 1) {
166	            /* (23a) */
167	            row_begin(b);
168	            c.rhs = 0;
169	            row_add(b, x->pa[t], 1.0);
170	            row_add(b, x->u[t], -range);
171	            add_v(&c, t, g->pmax - g->su);
172	            add_w(&c, t + 1, pos(g->su - g->sd));
173	            row_end(b, GRB_LESS_EQUAL, c.rhs);
174	            /* (23b) */
175	            row_begin(b);
176	            c.rhs = 0;
177	            row_add(b, x->pa[t], 1.0);
178	            row_add(b, x->u[t], -range);
179	            add_w(&c, t + 1, g->pmax - g->sd);
180	            add_v(&c, t, pos(g->sd - g->su));
181	            row_end(b, GRB_LESS_EQUAL, c.rhs);
182	        }
183	
184	        /* (38) */
185	        row_begin(b);
186	        c.rhs = 0;
187	        row_add(b, x->pa[t], 1.0);
188	        row_add(b, x->u[t], -range);
189	        add_w(&c, t + 1, g->pmax - g->sd);
190	        for (int i = 0; i <= imin(g->ut - 2, g->tru); i++)
191	            add_v(&c, t - i, g->pmax - g->su - i * g->ru);
192	        row_end(b, GRB_LESS_EQUAL, c.rhs);
193	
194	        /* (40) */
195	        if (g->tru > g->ut - 2) {
196	            row_begin(b);
197	            c.rhs = 0;
198	            row_add(b, x->pa[t], 1.0);
199	            row_add(b, x->u[t], -range);
200	            for (int i = 0; i <= imin(g->ut - 1, g->tru); i++)
201	                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
202	            row_end(b, GRB_LESS_EQUAL, c.rhs);
203	        }
204	
205	        /* (41): K^SD from (37); the printed K^SU refers to itself and is read with
206	         * [K^SD]^+ (NOTES.md). The left side is p', not pbar'. */
207	        int ksd = imin(imin(g->trd, g->ut - 1), T - t - 1);
208	        if (ksd > 0) {
209	            int ksu = imin(imin(g->tru, g->ut - 2 - ksd), t - 1);
210	            row_begin(b);
211	            c.rhs = 0;
212	            row_add(b, x->pp[t], 1.0);
213	            row_add(b, x->u[t], -range);
214	            for (int i = 0; i <= ksd; i++)
215	                add_w(&c, t + 1 + i, g->pmax - g->sd - i * g->rd);
216	            for (int i = 0; i <= ksu; i++)
217	                add_v(&c, t - i, g->pmax - g->su - i * g->ru);
218	            if (ksu < g->tru) {
219	                double a = g->su + (ksu + 1) * g->ru;
220	                double coef = 0;
221	                if (o->tail == TAIL_PRINTED) coef = pos(a - (g->sd + g->trd * g->rd));
222	                else if (o->tail == TAIL_CORRECTED) coef = pos((g->sd + ksd * g->rd) - a);
223	                add_v(&c, t - (ksu + 1), coef);
224	            }
225	            row_end(b, GRB_LESS_EQUAL, c.rhs);
226	        }
227	    }
228	}
