230	/* (35), (36). */
231	static void add_ramps(Builder *b, const Gen *g, const GenVars *x, int T) {
232	    const double pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
233	    for (int t = 1; t <= T; t++) {
234	        row_begin(b);
235	        row_add(b, x->pa[t], 1.0);
236	        if (t > 1) row_add(b, x->pp[t - 1], -1.0);
237	        row_add(b, x->v[t], -(g->su - g->pmin - g->ru));
238	        row_add(b, x->u[t], -g->ru);
239	        row_end(b, GRB_LESS_EQUAL, t == 1 ? pp0 : 0.0);
240	
241	        double rhs = 0;
242	        row_begin(b);
243	        if (t > 1) {
244	            row_add(b, x->pp[t - 1], 1.0);
245	            row_add(b, x->u[t - 1], -g->rd);
246	        } else {
247	            rhs = g->rd * g->on0 - pp0;
248	        }
249	        row_add(b, x->pp[t], -1.0);
250	        row_add(b, x->w[t], -(g->sd - g->pmin - g->rd));
251	        row_end(b, GRB_LESS_EQUAL, rhs);
252	    }
253	}
