255	/* C^v(l) or C^w(l) of (46): limit is SU or SD. */
256	static double seg_coef(const Gen *g, int l, double limit) {
257	    if (g->pw[l] <= limit) return 0.0;
258	    if (g->pw[l - 1] < limit) return g->pw[l] - limit;
259	    return g->pw[l] - g->pw[l - 1];
260	}
