262	/* (43), (46) or (48); (44) is substituted into the objective. */
263	static void add_piecewise(Builder *b, const Gen *g, const GenVars *x, int **pl, int T, const ModelOptions *o) {
264	    for (int t = 1; t <= T; t++) {
265	        RowCtx c = { b, g, x, T, o->no_hist_v, 0.0 };
266	        row_begin(b);
267	        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
268	        row_add(b, x->pp[t], -1.0);
269	        row_end(b, GRB_EQUAL, 0.0);
270	
271	        for (int l = 1; l <= g->nseg; l++) {
272	            double d = g->pw[l] - g->pw[l - 1];
273	            double cv = seg_coef(g, l, g->su), cw = seg_coef(g, l, g->sd);
274	            if (g->ut > 1) {
275	                /* (46) */
276	                row_begin(b);
277	                row_add(b, pl[l][t], 1.0);
278	                row_add(b, x->u[t], -d);
279	                add_v(&c, t, cv);
280	                add_w(&c, t + 1, cw);
281	                row_end(b, GRB_LESS_EQUAL, 0.0);
282	            } else {
283	                /* (48). The printed operands of [.]^+ are reversed relative to (23);
284	                 * see NOTES.md. */
285	                double to_w = o->pw48_printed ? pos(cv - cw) : pos(cw - cv);
286	                double to_v = o->pw48_printed ? pos(cw - cv) : pos(cv - cw);
287	                row_begin(b);
288	                row_add(b, pl[l][t], 1.0);
289	                row_add(b, x->u[t], -d);
290	                add_v(&c, t, cv);
291	                add_w(&c, t + 1, to_w);
292	                row_end(b, GRB_LESS_EQUAL, 0.0);
293	                row_begin(b);
294	                row_add(b, pl[l][t], 1.0);
295	                row_add(b, x->u[t], -d);
296	                add_w(&c, t + 1, cw);
297	                add_v(&c, t, to_v);
298	                row_end(b, GRB_LESS_EQUAL, 0.0);
299	            }
300	        }
301	    }
302	}
