304	/* A basic physical model built from (18), (19), (24), (25), (43), (42): the same
305	 * integer feasible set as T, with none of T's strengthening. Used only to test T. */
306	static void add_base_physical(Builder *b, const Gen *g, const GenVars *x, int **pl, int T) {
307	    const double range = g->pmax - g->pmin, pp0 = g->on0 ? g->p0 - g->pmin : 0.0;
308	    for (int t = 1; t <= T; t++) {
309	        RowCtx c = { b, g, x, T, 1, 0.0 };
310	        row_begin(b);
311	        row_add(b, x->pp[t], 1.0);
312	        row_add(b, x->pa[t], -1.0);
313	        row_end(b, GRB_LESS_EQUAL, 0.0);
314	        row_begin(b);
315	        row_add(b, x->pa[t], 1.0);
316	        row_add(b, x->u[t], -range);
317	        add_w(&c, t + 1, g->pmax - g->sd);
318	        row_end(b, GRB_LESS_EQUAL, 0.0);
319	
320	        /* (24) */
321	        double rhs = 0;
322	        row_begin(b);
323	        row_add(b, x->pa[t], 1.0);
324	        row_add(b, x->u[t], g->pmin);
325	        row_add(b, x->v[t], -g->su);
326	        if (t > 1) {
327	            row_add(b, x->pp[t - 1], -1.0);
328	            row_add(b, x->u[t - 1], -g->pmin - g->ru);
329	        } else {
330	            rhs = pp0 + g->on0 * (g->pmin + g->ru);
331	        }
332	        row_end(b, GRB_LESS_EQUAL, rhs);
333	        /* (25) */
334	        rhs = 0;
335	        row_begin(b);
336	        if (t > 1) {
337	            row_add(b, x->pp[t - 1], 1.0);
338	            row_add(b, x->u[t - 1], g->pmin);
339	        } else {
340	            rhs = -pp0 - g->on0 * g->pmin;
341	        }
342	        row_add(b, x->pp[t], -1.0);
343	        row_add(b, x->u[t], -g->pmin - g->rd);
344	        row_add(b, x->w[t], -g->sd);
345	        row_end(b, GRB_LESS_EQUAL, rhs);
346	
347	        row_begin(b);
348	        for (int l = 1; l <= g->nseg; l++) row_add(b, pl[l][t], 1.0);
349	        row_add(b, x->pp[t], -1.0);
350	        row_end(b, GRB_EQUAL, 0.0);
351	        for (int l = 1; l <= g->nseg; l++) {
352	            row_begin(b);
353	            row_add(b, pl[l][t], 1.0);
354	            row_add(b, x->u[t], -(g->pw[l] - g->pw[l - 1]));
355	            row_end(b, GRB_LESS_EQUAL, 0.0);
356	        }
357	    }
358	}
