360	/* Variables x(t',t) of (59)-(61), for shut-down at t' and start-up at t with
361	 * DT <= t-t' <= TC-1, and the rows (59), (60). Their objective coefficients are
362	 * those of (61) after substitution into (69). Only one historical shut-down
363	 * exists: t' = 1-down0 for a unit that is off at period 0. */
364	static void add_startup(Builder *b, const Gen *g, const GenVars *x, int T) {
365	    const int S = g->ncat;
366	    if (S < 2 || g->tc <= g->dt) return;
367	    const double cold = g->scost[S - 1];
368	    int *xh = new_index(T);
369	    int *xm = xrealloc(NULL, (size_t)(T + 2) * (size_t)(T + 2) * sizeof(int));
370	    for (int k = 0; k < (T + 2) * (T + 2); k++) xm[k] = -1;
371	
372	#define XM(tp, t) xm[(tp) * (T + 2) + (t)]
373	    for (int t = 1; t <= T; t++) {
374	        for (int tp = t - g->tc + 1; tp <= t - g->dt; tp++) {
375	            if (tp < 1 && !gen_hist_w(g, tp)) continue;
376	            int s = 0;
377	            while (s + 1 < S && g->lag[s + 1] <= t - tp) s++;
378	            int col = add_binary(b, -(cold - g->scost[s]), 0.0, 1.0);
379	            if (tp >= 1) XM(tp, t) = col;
380	            else xh[t] = col;
381	        }
382	    }
383	    /* (59) */
384	    for (int t = 1; t <= T; t++) {
385	        int any = 0;
386	        row_begin(b);
387	        for (int tp = 1; tp < t; tp++)
388	            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
389	        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
390	        if (any) {
391	            row_add(b, x->v[t], -1.0);
392	            row_end(b, GRB_LESS_EQUAL, 0.0);
393	        } else {
394	            b->nnz = b->beg[b->nrow];
395	        }
396	    }
397	    /* (60) */
398	    for (int tp = 1; tp <= T; tp++) {
399	        int any = 0;
400	        row_begin(b);
401	        for (int t = tp + 1; t <= T; t++)
402	            if (XM(tp, t) >= 0) { row_add(b, XM(tp, t), 1.0); any = 1; }
403	        if (any) {
404	            row_add(b, x->w[tp], -1.0);
405	            row_end(b, GRB_LESS_EQUAL, 0.0);
406	        } else {
407	            b->nnz = b->beg[b->nrow];
408	        }
409	    }
410	    /* (60) at the historical shut-down, where w = 1 */
411	    int any = 0;
412	    row_begin(b);
413	    for (int t = 1; t <= T; t++)
414	        if (xh[t] >= 0) { row_add(b, xh[t], 1.0); any = 1; }
415	    if (any) row_end(b, GRB_LESS_EQUAL, 1.0);
416	    else b->nnz = b->beg[b->nrow];
417	#undef XM
418	    free(xm);
419	    free(xh);
420	}
