553	void varmap_free(VarMap *m) {
554	    if (!m) return;
555	    for (int g = 0; g < m->ngen; g++) {
556	        free(m->gen[g].u); free(m->gen[g].v); free(m->gen[g].w);
557	        free(m->gen[g].pp); free(m->gen[g].pa);
558	    }
559	    free(m->gen);
560	    free(m->pw); free(m->splus); free(m->sminus); free(m->sr);
561	    free(m);
562	}
