32	static int get_num(const JsonValue *o, const char *key, const char *ctx, double *out,
33	                   char *err, unsigned long errlen) {
34	    const JsonValue *v = json_get(o, key);
35	    if (!v) return seterr(err, errlen, "%s: missing field '%s'", ctx, key);
36	    if (v->type != JSON_NUMBER && v->type != JSON_BOOL)
37	        return seterr(err, errlen, "%s: field '%s' is not a number", ctx, key);
38	    *out = v->number;
