70	/* Evaluate the file's cost curve at mw, extending the end segments if needed. */
71	static double curve_value(const double *mw, const double *cost, int n, double x) {
72	    if (n == 1) return cost[0];
73	    int k = 0;
74	    while (k < n - 2 && x > mw[k + 1]) k++;
75	    double d = mw[k + 1] - mw[k];
76	    if (d <= 0) return cost[k];
77	    return cost[k] + (cost[k + 1] - cost[k]) * (x - mw[k]) / d;
78	}
