80	static int load_startup(Instance *inst, Gen *g, const JsonValue *jg, char *err, unsigned long errlen) {
81	    const JsonValue *js = json_get(jg, "startup");
82	    if (!js || js->type != JSON_ARRAY || js->count == 0)
83	        return seterr(err, errlen, "%s: 'startup' must be a non-empty array", g->name);
84	    int n = (int)js->count;
85	    int *lag = xcalloc((size_t)n, sizeof *lag);
86	    double *cost = xcalloc((size_t)n, sizeof *cost);
87	    for (int k = 0; k < n; k++) {
88	        int r = 0;
89	        if (!get_int(&js->items[k], "lag", g->name, &lag[k], &r, err, errlen) ||
90	            !get_num(&js->items[k], "cost", g->name, &cost[k], err, errlen)) {
91	            free(lag); free(cost);
92	            return 0;
93	        }
94	        inst->n_int_rounded += r;
95	        if (k > 0 && lag[k] <= lag[k - 1]) inst->n_lag_not_increasing++;
96	        if (k > 0 && cost[k] < cost[k - 1]) inst->n_scost_decreasing++;
97	    }
98	    if (lag[0] < g->dt) inst->n_lag_first_lt_dt++;
99	    if (lag[0] > g->dt) inst->n_lag_first_gt_dt++;
100	
101	    /* Paper: T^1 = DT and T^S = TC. An off period shorter than DT cannot occur, so
102	     * a category whose whole range lies below DT is unreachable and is dropped.
103	     * The last category with lag <= DT becomes the hottest; if every lag exceeds
104	     * DT, the first category is extended down to DT. */
105	    int first = 0;
106	    for (int k = 0; k < n; k++) if (lag[k] <= g->dt) first = k;
107	    if (first > 0) inst->n_cat_merged++;
108	    g->ncat = n - first;
109	    g->lag = xcalloc((size_t)g->ncat, sizeof *g->lag);
110	    g->scost = xcalloc((size_t)g->ncat, sizeof *g->scost);
111	    for (int k = 0; k < g->ncat; k++) {
112	        g->lag[k] = lag[first + k];
113	        g->scost[k] = cost[first + k];
114	    }
115	    g->lag[0] = g->dt;
116	    g->tc = g->lag[g->ncat - 1];
117	    free(lag);
118	    free(cost);
119	    return 1;
120	}
