122	static int load_curve(Instance *inst, Gen *g, const JsonValue *jg, char *err, unsigned long errlen) {
123	    const JsonValue *jp = json_get(jg, "piecewise_production");
124	    if (!jp || jp->type != JSON_ARRAY || jp->count == 0)
125	        return seterr(err, errlen, "%s: 'piecewise_production' must be a non-empty array", g->name);
126	    int n = (int)jp->count;
127	    double *mw = xcalloc((size_t)n, sizeof *mw);
128	    double *cost = xcalloc((size_t)n, sizeof *cost);
129	    for (int k = 0; k < n; k++) {
130	        if (!get_num(&jp->items[k], "mw", g->name, &mw[k], err, errlen) ||
131	            !get_num(&jp->items[k], "cost", g->name, &cost[k], err, errlen)) {
132	            free(mw); free(cost);
133	            return 0;
134	        }
135	    }
136	    int dup = 0, nonconvex = 0;
137	    double prev = -INFINITY;
138	    for (int k = 1; k < n; k++) {
139	        double d = mw[k] - mw[k - 1];
140	        if (d <= MW_TOL) { dup = 1; continue; }
141	        double s = (cost[k] - cost[k - 1]) / d;
142	        if (s < prev - 1e-7) nonconvex = 1;
143	        prev = s;
144	    }
145	    if (dup) inst->n_pw_dup++;
146	    if (nonconvex) inst->n_pw_nonconvex++;
147	    if (fabs(mw[0] - g->pmin) > MW_TOL) inst->n_pw_first_ne_pmin++;
148	    if (fabs(mw[n - 1] - g->pmax) > MW_TOL) inst->n_pw_last_ne_pmax++;
149	
150	    /* Paper: Pbar^0 = P_ and Pbar^l > P_ for every l. Restrict the curve to
151	     * [Pmin, Pmax], interpolating at the ends and dropping repeated points. */
152	    g->cr = curve_value(mw, cost, n, g->pmin);
153	    g->pw = xcalloc((size_t)n + 2, sizeof *g->pw);
154	    g->slope = xcalloc((size_t)n + 2, sizeof *g->slope);
155	    g->pw[0] = g->pmin;
156	    int L = 0;
157	    double last_cost = g->cr;
158	    for (int k = 0; k < n; k++) {
159	        if (mw[k] <= g->pw[L] + MW_TOL) continue;
160	        if (mw[k] >= g->pmax - MW_TOL) break;
161	        L++;
162	        g->pw[L] = mw[k];
163	        g->slope[L] = (cost[k] - last_cost) / (g->pw[L] - g->pw[L - 1]);
164	        last_cost = cost[k];
165	    }
166	    if (g->pmax > g->pw[L] + MW_TOL) {
167	        double c = curve_value(mw, cost, n, g->pmax);
168	        L++;
169	        g->pw[L] = g->pmax;
170	        g->slope[L] = (c - last_cost) / (g->pw[L] - g->pw[L - 1]);
171	    }
172	    g->nseg = L;
173	    free(mw);
174	    free(cost);
175	    return 1;
176	}
