221	Instance *instance_load(const char *path, char *err, unsigned long errlen) {
222	    JsonValue *root = json_parse_file(path, err, errlen);
223	    if (!root) return NULL;
224	    Instance *inst = xcalloc(1, sizeof *inst);
225	    int ok = 0;
226	
227	    do {
228	        if (root->type != JSON_OBJECT) { seterr(err, errlen, "top level is not an object"); break; }
229	        int r = 0;
230	        if (!get_int(root, "time_periods", "top level", &inst->T, &r, err, errlen)) break;
231	        int T = inst->T;
232	        if (T < 1) { seterr(err, errlen, "time_periods must be positive"); break; }
233	        inst->demand = xcalloc((size_t)T + 2, sizeof(double));
234	        inst->reserve = xcalloc((size_t)T + 2, sizeof(double));
235	        inst->ren_min = xcalloc((size_t)T + 2, sizeof(double));
236	        inst->ren_max = xcalloc((size_t)T + 2, sizeof(double));
237	        if (!get_series(root, "demand", "top level", T, inst->demand + 1, err, errlen)) break;
238	        if (!get_series(root, "reserves", "top level", T, inst->reserve + 1, err, errlen)) break;
239	
240	        const JsonValue *jr = json_get(root, "renewable_generators");
241	        if (!jr || jr->type != JSON_OBJECT) { seterr(err, errlen, "missing 'renewable_generators'"); break; }
242	        inst->nren = (int)jr->count;
243	        double *lo = xcalloc((size_t)T, sizeof *lo), *hi = xcalloc((size_t)T, sizeof *hi);
244	        int good = 1;
245	        for (size_t k = 0; k < jr->count && good; k++) {
246	            good = get_series(&jr->items[k], "power_output_minimum", jr->keys[k], T, lo, err, errlen) &&
247	                   get_series(&jr->items[k], "power_output_maximum", jr->keys[k], T, hi, err, errlen);
248	            for (int t = 0; good && t < T; t++) {
249	                inst->ren_min[t + 1] += lo[t];
250	                inst->ren_max[t + 1] += hi[t];
251	            }
252	        }
253	        free(lo);
254	        free(hi);
255	        if (!good) break;
256	
257	        const JsonValue *jt = json_get(root, "thermal_generators");
258	        if (!jt || jt->type != JSON_OBJECT) { seterr(err, errlen, "missing 'thermal_generators'"); break; }
259	        inst->ngen = (int)jt->count;
260	        inst->gen = xcalloc((size_t)inst->ngen, sizeof *inst->gen);
261	        for (int g = 0; g < inst->ngen && good; g++)
262	            good = load_gen(inst, &inst->gen[g], jt->keys[g], &jt->items[g], err, errlen);
263	        if (!good) break;
264	        ok = 1;
265	    } while (0);
266	
267	    json_free(root);
268	    if (!ok) { instance_free(inst); return NULL; }
269	    return inst;
270	}
