272	void instance_free(Instance *inst) {
273	    if (!inst) return;
274	    if (inst->gen) {
275	        for (int g = 0; g < inst->ngen; g++) {
276	            free(inst->gen[g].name);
277	            free(inst->gen[g].lag);
278	            free(inst->gen[g].scost);
279	            free(inst->gen[g].pw);
280	            free(inst->gen[g].slope);
281	        }
282	    }
283	    free(inst->gen);
284	    free(inst->demand);
285	    free(inst->reserve);
286	    free(inst->ren_min);
287	    free(inst->ren_max);
288	    free(inst);
289	}
