291	static int warn(FILE *out, const char *what, int count, const char *example) {
292	    if (count == 0) return 0;
293	    fprintf(out, "data warning: %s: %d", what, count);
294	    if (example) fprintf(out, " (e.g. %s)", example);
295	    fputc('\n', out);
296	    return 1;
297	}
