299	int instance_warnings(const Instance *in, FILE *out) {
300	    enum {
301	        UT_GT_T, DT_GT_T, SU_LT_PMIN, SD_LT_PMIN, SU_GT_PMAX, SD_GT_PMAX, MUST_OFF, MUST_DOWN,
302	        P0_LOW, P0_HIGH, ON_NO_UP, ON_DOWN, OFF_P0, OFF_NO_DOWN, OFF_UP,
303	        HIST_TRAJ, CANNOT_STAY, NKIND
304	    };
305	    static const char *label[NKIND] = {
306	        "generators with UT > T",
307	        "generators with DT > T",
308	        "generators with SU below minimum power (cannot start)",
309	        "generators with SD below minimum power (cannot stop)",
310	        "generators with SU above maximum power (clipped)",
311	        "generators with SD above maximum power (clipped)",
312	        "must-run generators off in period 0",
313	        "must-run generators required to stay off at the start",
314	        "generators on in period 0 below minimum power",
315	        "generators on in period 0 above maximum power",
316	        "generators on in period 0 with time_up_t0 <= 0",
317	        "generators on in period 0 with time_down_t0 != 0",
318	        "generators off in period 0 with nonzero output",
319	        "generators off in period 0 with time_down_t0 <= 0",
320	        "generators off in period 0 with time_up_t0 != 0",
321	        "generators whose p(0) exceeds SU + (time_up_t0-1) RU, contradicting historical v",
322	        "generators on in period 0 that can neither shut down nor reach minimum power",
323	    };
324	    int count[NKIND] = { 0 };
325	    const char *first[NKIND] = { 0 };
326	#define FLAG(kind) do { if (!count[kind]++) first[kind] = g->name; } while (0)
327	    for (int i = 0; i < in->ngen; i++) {
328	        const Gen *g = &in->gen[i];
329	        if (g->ut > in->T) FLAG(UT_GT_T);
330	        if (g->dt > in->T) FLAG(DT_GT_T);
331	        if (g->su_raw < g->pmin - MW_TOL) FLAG(SU_LT_PMIN);
332	        if (g->sd_raw < g->pmin - MW_TOL) FLAG(SD_LT_PMIN);
333	        if (g->su_raw > g->pmax + MW_TOL) FLAG(SU_GT_PMAX);
334	        if (g->sd_raw > g->pmax + MW_TOL) FLAG(SD_GT_PMAX);
335	        if (g->must_run && !g->on0) FLAG(MUST_OFF);
336	        if (g->must_run && g->need_down) FLAG(MUST_DOWN);
337	        if (g->on0) {
338	            if (g->p0 < g->pmin - MW_TOL) FLAG(P0_LOW);
339	            if (g->p0 > g->pmax + MW_TOL) FLAG(P0_HIGH);
340	            if (g->up0 <= 0) FLAG(ON_NO_UP);
341	            if (g->down0 != 0) FLAG(ON_DOWN);
342	            if (g->up0 > 0 && g->p0 > g->su + (g->up0 - 1) * g->ru + 1e-7) FLAG(HIST_TRAJ);
343	            if (g->p0 > g->sd + MW_TOL && g->p0 + g->ru < g->pmin - MW_TOL) FLAG(CANNOT_STAY);
344	        } else {
345	            if (g->p0 != 0) FLAG(OFF_P0);
346	            if (g->down0 <= 0) FLAG(OFF_NO_DOWN);
347	            if (g->up0 != 0) FLAG(OFF_UP);
348	        }
349	    }
350	#undef FLAG
351	    int lines = 0;
352	    for (int k = 0; k < NKIND; k++) lines += warn(out, label[k], count[k], first[k]);
353	    lines += warn(out, "generators whose name field differs from their key", in->n_name_mismatch, NULL);
354	    lines += warn(out, "generators whose first start-up lag is below DT", in->n_lag_first_lt_dt, NULL);
355	    lines += warn(out, "generators whose first start-up lag is above DT", in->n_lag_first_gt_dt, NULL);
356	    lines += warn(out, "generators with start-up categories unreachable because of DT", in->n_cat_merged, NULL);
357	    lines += warn(out, "start-up lags not strictly increasing", in->n_lag_not_increasing, NULL);
358	    lines += warn(out, "start-up costs that decrease with lag", in->n_scost_decreasing, NULL);
359	    lines += warn(out, "curves whose first point is not at minimum power", in->n_pw_first_ne_pmin, NULL);
360	    lines += warn(out, "curves whose last point is not at maximum power", in->n_pw_last_ne_pmax, NULL);
361	    lines += warn(out, "curves with repeated mw points", in->n_pw_dup, NULL);
362	    lines += warn(out, "curves that are not convex", in->n_pw_nonconvex, NULL);
363	    lines += warn(out, "integer fields with non-integer values (rounded)", in->n_int_rounded, NULL);
364	    return lines;
365	}
