1	/* uc_solve [--relax] [--time-limit SECONDS] [--solution FILE] instance.json
2	 *
3	 * Two further options are documented in NOTES.md: --log FILE keeps the Gurobi log,
4	 * and --variant NAME selects a diagnostic departure from the default model. */
5	#include "model.h"
6	
7	#include <math.h>
8	#include <stdio.h>
9	#include <stdlib.h>
10	#include <string.h>
11	
12	static void usage(void) {
13	    fprintf(stderr,
14	            "usage: uc_solve [--relax] [--time-limit SECONDS] [--solution FILE] "
15	            "[--log FILE] [--variant NAME] instance.json\n");
16	}
