18	static void csv_name(FILE *f, const char *s) {
19	    if (!strpbrk(s, ",\"\r\n")) { fputs(s, f); return; }
20	    fputc('"', f);
21	    for (; *s; s++) {
22	        if (*s == '"') fputc('"', f);
23	        fputc(*s, f);
24	    }
25	    fputc('"', f);
26	}
27	
28	static double nonneg(double x) { return x > 0 ? x : 0; }
29	
30	static int write_solution(const char *path, const Instance *in, const VarMap *m,
31	                          const double *x, int relax) {
32	    FILE *f = fopen(path, "w");
33	    if (!f) { fprintf(stderr, "cannot open %s for writing\n", path); return 1; }
34	    fprintf(f, "generator,period,on,power,available\n");
35	    for (int gi = 0; gi < in->ngen; gi++) {
36	        const Gen *g = &in->gen[gi];
37	        const GenVars *v = &m->gen[gi];
38	        for (int t = 1; t <= in->T; t++) {
39	            int on = x[v->u[t]] >= 0.5;
40	            /* In a MIP solution u is rounded to remove integrality noise. In an LP
41	             * solution p = p' + P_ u must use the fractional u. */
42	            double uval = relax ? x[v->u[t]] : (double)on;
43	            double power = nonneg(x[v->pp[t]]) + g->pmin * uval;
44	            double avail = nonneg(x[v->pa[t]]) + g->pmin * uval;
45	            if (avail < power) avail = power;
46	            csv_name(f, g->name);
47	            fprintf(f, ",%d,%d,%.6f,%.6f\n", t, on, power, avail);
48	        }
49	    }
50	    for (int t = 1; t <= in->T; t++)
51	        fprintf(f, "RENEWABLE,%d,,%.6f,\n", t, x[m->pw[t]]);
52	    if (fclose(f) != 0) { fprintf(stderr, "error writing %s\n", path); return 1; }
53	    return 0;
54	}
