70	#define CHECK(call)                                                                 \
71	    do {                                                                            \
72	        int err_ = (call);                                                          \
73	        if (err_) {                                                                 \
74	            fprintf(stderr, "Gurobi error %d at %s:%d: %s\n", err_, __FILE__,       \
